const state={novel:window.APP_STATE?.novel||null,chapter:Number(window.APP_STATE?.chapter||0),editing:0,generating:false,characters:[],controller:null,activeTask:null,settings:{auto_save_drafts:true}};
let promptSettings={};
function renderPromptSettings(prompts){promptSettings=prompts||{};let box=$('promptSettingsBox');if(!box){box=document.createElement('div');box.id='promptSettingsBox';box.innerHTML='<div class="prompt-settings-head"><h3>AI 提示词设置</h3><button type="button" class="secondary" id="resetPrompts">恢复默认</button></div><p class="hint">按任务分类修改。留空表示不追加自定义规则；修改后下一次模型调用立即生效。</p><div id="promptSettingsCategories"></div>';$('modelSettingsInfo').before(box);box.querySelector('#resetPrompts').onclick=async()=>{if(!confirm('恢复所有分类的默认提示词？'))return;const data=await json('/api/settings/prompts/reset',{method:'POST'});renderPromptSettings(data.prompts);toast('提示词已恢复默认')}}const categories=$('promptSettingsCategories');categories.innerHTML=Object.entries(promptSettings).map(([category,entries])=>`<details class="prompt-category"><summary>${escapeHtml(category)} <small>${Object.keys(entries).length}项</small></summary>${Object.entries(entries).map(([key,item])=>`<label>${escapeHtml(item.label)}<textarea rows="4" data-prompt-category="${escapeHtml(category)}" data-prompt-key="${escapeHtml(key)}">${escapeHtml(item.instruction||'')}</textarea></label>`).join('')}</details>`).join('')}
function collectPromptSettings(){document.querySelectorAll('[data-prompt-key]').forEach(area=>{promptSettings[area.dataset.promptCategory][area.dataset.promptKey].instruction=area.value});return promptSettings}
function renderModelManager(status,settings={}){let box=$('modelManagerBox');if(!box){box=document.createElement('div');box.id='modelManagerBox';$('modelSettingsInfo').before(box)}const models=status.loaded_models||[];box.innerHTML=`<div class="prompt-settings-head"><h3>本地模型管理</h3><span class="model-dot ${status.loaded?'online':''}">${status.loaded?'已连接':'未连接'}</span></div><div class="two"><label>随机种子模式<select id="settingSeedMode"><option value="random">每次随机（推荐创作）</option><option value="fixed">固定种子（用于复现）</option></select></label><label>固定种子<input id="settingFixedSeed" type="number" min="0" max="2147483647"></label></div><p class="hint">随机模式每次请求生成新seed；固定模式在提示词和参数相同时尽量复现结果。</p><div class="model-actions"><button type="button" class="secondary" id="clearVram">从LMS卸载Ornith</button><button type="button" class="secondary" id="reloadModel">重新连接并预热</button><button type="button" class="danger" id="clearConversations">清空对话与任务记录</button></div><div class="list-card">${models.map(model=>`<div class="chapter-row"><b>${escapeHtml(model.identifier||model.id||model.path||'已加载模型')}</b><small>${escapeHtml(model.type||model.architecture||'')}</small></div>`).join('')||'<p class="hint">当前没有模型驻留内存。</p>'}</div><p class="hint">模型加载参数完全由 LM Studio 管理；项目不会覆盖上下文、GPU、CPU专家层、KV、Flash Attention、MTP或聊天模板。卸载后请在 LM Studio 按保存参数重新加载。</p>`;$('settingSeedMode').value=settings.seed_mode||'random';$('settingFixedSeed').value=settings.fixed_seed??42;box.querySelector('#clearVram').onclick=()=>modelAction('/api/model/clear-vram','确定从 LM Studio 卸载 Ornith 并释放显存？');box.querySelector('#reloadModel').onclick=()=>modelAction('/api/model/reload');box.querySelector('#clearConversations').onclick=clearConversations}
function renderPerformancePanel(status){let box=$('performanceBox');if(!box){box=document.createElement('section');box.id='performanceBox';box.className='performance-card';$('modelSettingsInfo').before(box)}const performance=status.performance||{},history=performance.history||[],last=status.last_metrics||{},bench=history.filter(item=>item.label==='benchmark').slice(-3),avg=bench.length?(bench.reduce((sum,item)=>sum+Number(item.tokens_per_second||0),0)/bench.length).toFixed(2):'--';box.innerHTML=`<header><div><h3>性能与硬件档案</h3><small>三轮固定正文测试自动排除预热</small></div><div><button type="button" class="secondary" id="scanGpu">扫描显存</button> <button type="button" class="secondary" id="warmupModel">预热</button> <button type="button" class="primary" id="benchmarkModel">运行三轮基准</button></div></header><div class="performance-metrics"><span><small>最近正文速度</small><b>${last.tokens_per_second||'--'} t/s</b></span><span><small>预填充速度</small><b>${last.prompt_tokens_per_second||'--'} t/s</b></span><span><small>缓存命中</small><b>${last.cached_prompt_tokens||0} tokens</b></span><span><small>首 Token</small><b>${last.time_to_first_token??'--'} s</b></span><span><small>三轮平均</small><b id="benchmarkAverage">${avg} t/s</b></span></div><div id="gpuProcessList" class="gpu-process-list"></div><div class="benchmark-runs" id="benchmarkRuns">${bench.map(item=>`${escapeHtml(item.at||'')} · ${item.tokens_per_second} token/s · ${item.completion_tokens||0} tokens`).join('<br>')||'还没有基准记录'}</div><div class="profile-row"><input id="profileName" value="${escapeHtml(performance.active_profile||'balanced')}" placeholder="档案名称"><input id="profileExperts" type="number" min="0" max="64" value="18" placeholder="CPU专家数"><button type="button" class="secondary" id="saveProfile">保存当前硬件档案</button></div><p class="hint">档案用于记录 LM Studio 外部参数，不会擅自修改驱动或超频设置。</p>`;box.querySelector('#scanGpu').onclick=scanGpuProcesses;box.querySelector('#warmupModel').onclick=async()=>{try{setBusy($('warmupModel'),true,'预热中…');const data=await json('/api/model/warmup',{method:'POST'});toast(`预热完成 · ${data.metrics.tokens_per_second||0} token/s`)}catch(error){toast(error.message,true)}finally{setBusy($('warmupModel'),false,'预热')}};box.querySelector('#benchmarkModel').onclick=async()=>{try{setBusy($('benchmarkModel'),true,'三轮测试中…');runtimeLog('正在运行三轮固定模型基准');const data=await json('/api/model/benchmark',{method:'POST'});$('benchmarkAverage').textContent=`${data.average_tokens_per_second} t/s`;$('benchmarkRuns').innerHTML=data.runs.map(item=>`第${item.run}轮 · ${item.tokens_per_second} token/s · ${item.elapsed_seconds}秒`).join('<br>');runtimeLog(`基准完成 · 热态平均 ${data.average_tokens_per_second} token/s`)}catch(error){toast(error.message,true)}finally{setBusy($('benchmarkModel'),false,'运行三轮基准')}};box.querySelector('#saveProfile').onclick=async()=>{try{await json('/api/model/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('profileName').value,runtime:'Vulkan',cpu_experts:Number($('profileExperts').value),context_length:131072,note:'Vulkan直连硬件参数记录'})});toast('硬件档案已保存')}catch(error){toast(error.message,true)}}}
const renderManagedPerformancePanel=renderPerformancePanel;
renderPerformancePanel=function(status){renderManagedPerformancePanel(status);const box=$('performanceBox'),model=(status.loaded_models||[])[0]||{},contextLength=Number(model.contextLength||model.context_length||32768),expertInput=box?.querySelector('#profileExperts');expertInput?.remove();const hint=box?.querySelector('.profile-row + .hint');if(hint)hint.textContent='项目只记录 LMS 当前实例的实测性能，不会修改 LM Studio 加载参数、驱动或超频设置。';const save=box?.querySelector('#saveProfile');if(save)save.onclick=async()=>{try{await json('/api/model/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('profileName').value,runtime:'LM Studio managed',context_length:contextLength,note:'Ornith LMS托管实例性能记录；加载参数以LM Studio为准'})});toast('LMS实例性能档案已保存')}catch(error){toast(error.message,true)}}};
async function scanGpuProcesses(){try{setBusy($('scanGpu'),true,'扫描中…');const data=await json('/api/model/gpu-processes'),box=$('gpuProcessList');box.innerHTML=`<p class="hint">当前专用显存合计 ${Math.round(data.total_mb)} MB；受保护进程不会提供关闭按钮。</p>${data.processes.map(item=>`<div class="gpu-process-row"><span><b>${escapeHtml(item.name)}</b><small>PID ${item.pid} · ${item.vram_mb} MB</small></span>${item.protected?'<em>受保护</em>':`<button type="button" class="secondary gpu-close" data-pid="${item.pid}">关闭</button>`}</div>`).join('')}`;box.querySelectorAll('.gpu-close').forEach(button=>button.onclick=async()=>{if(!confirm('关闭该程序可能丢失未保存内容，确定继续？'))return;try{await json(`/api/model/gpu-processes/${button.dataset.pid}/close`,{method:'POST'});toast('已请求关闭程序');await scanGpuProcesses()}catch(error){toast(error.message,true)}})}catch(error){toast(error.message,true)}finally{setBusy($('scanGpu'),false,'扫描显存')}}
async function modelAction(url,confirmation=''){try{if(confirmation&&!confirm(confirmation))return;runtimeLog(url.endsWith('reload')?'正在重载本地模型':'正在卸载本地模型');const data=await json(url,{method:'POST'});toast(data.message||'模型操作完成');renderModelManager(await json('/api/model/status'))}catch(error){toast(error.message,true)}}
async function clearConversations(){try{if(!confirm('清空所有任务日志、运行记录和浏览器对话草稿？'))return;const data=await json('/api/model/clear-conversations',{method:'POST'});Object.keys(localStorage).filter(key=>key.startsWith('novel-draft:')||key==='novel-active-task').forEach(key=>localStorage.removeItem(key));toast(data.message||'对话记录已清空')}catch(error){toast(error.message,true)}}
const $=id=>document.getElementById(id);
const enc=value=>encodeURIComponent(value);
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('toast').append(node);setTimeout(()=>node.remove(),3200)}
async function json(url,options={}){const response=await fetch(url,options);let data={};try{data=await response.json()}catch{}if(!response.ok||data.success===false)throw new Error(data.error||`请求失败 (${response.status})`);return data}
function form(data){const body=new FormData();Object.entries(data).forEach(([key,value])=>body.append(key,value??''));return body}
async function post(url,data){return json(url,{method:'POST',body:form(data)})}
function setBusy(element,busy,label){if(!element)return;element.disabled=busy;element.classList.toggle('loading',busy);if(label)element.textContent=label}
function runtimeLog(message,kind='stage'){const box=$('runtimeLog');if(!box)return;$('runtime').classList.add('show');const row=document.createElement('p');row.className=kind;row.innerHTML=`<time>${new Date().toLocaleTimeString('en-US',{hour12:false})}</time> ${escapeHtml(message)}`;box.append(row);box.scrollTop=box.scrollHeight}
function runtimeProgress(value){if($('runtimeBar'))$('runtimeBar').style.width=`${Math.max(0,Math.min(100,value))}%`}
function planLog(message,progress){$('planConsole').classList.add('show');$('planStatus').textContent=message;$('planPercent').textContent=`${progress}%`;$('planBar').style.width=`${progress}%`;const row=document.createElement('p');row.innerHTML=`<time>${new Date().toLocaleTimeString('en-US',{hour12:false})}</time> ${escapeHtml(message)}`;$('planLog').append(row);$('planLog').scrollTop=$('planLog').scrollHeight}
async function readEventStream(response,onEvent){if(!response.ok)throw new Error((await response.json()).error||`请求失败 (${response.status})`);const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';while(true){const {done,value}=await reader.read();if(done)break;pending+=decoder.decode(value,{stream:true});const blocks=pending.split('\n\n');pending=blocks.pop();for(const block of blocks){const line=block.split('\n').find(item=>item.startsWith('data: '));if(!line)continue;const raw=line.slice(6);if(raw==='[DONE]')continue;const data=JSON.parse(raw);if(data.task_id){state.activeTask=data.task_id;localStorage.setItem('novel-active-task',data.task_id)}if(data.brief&&$('currentChapterBrief'))$('currentChapterBrief').textContent=`${data.brief.title||''}：${data.brief.synopsis||''}`;if(data.message&&$('runtime')){runtimeLog(data.message,data.type||'stage');if(Number.isFinite(data.progress))runtimeProgress(data.progress)}onEvent(data)}}}
$('runtimeToggle')?.addEventListener('click',()=>{const collapsed=$('runtime').classList.toggle('collapsed');$('runtimeToggle').textContent=collapsed?'展开':'收起'});
if($('runtimeCancel')&&!$('runtimePause')){const pause=document.createElement('button');pause.id='runtimePause';pause.textContent='暂停';$('runtimeCancel').before(pause);pause.onclick=async()=>{if(!state.activeTask)return toast('当前没有后台任务');try{const paused=pause.dataset.paused==='1';await post(`/api/tasks/${state.activeTask}/${paused?'resume':'pause'}`,{});pause.dataset.paused=paused?'0':'1';pause.textContent=paused?'暂停':'继续';runtimeLog(paused?'任务已重新排队':'将在当前模型调用结束后暂停','warning')}catch(error){toast(error.message,true)}}}
$('runtimeCancel')?.addEventListener('click',async()=>{if(!state.controller&&!state.activeTask)return toast('当前没有运行中的任务');if(state.controller)state.controller.abort();if(state.activeTask){try{await post(`/api/tasks/${state.activeTask}/cancel`,{})}catch{}}runtimeLog('用户已停止当前任务','error');state.controller=null;state.activeTask=null;localStorage.removeItem('novel-active-task')});
async function restoreTaskCenter(){if(!state.novel||!$('runtime'))return;try{const remembered=localStorage.getItem('novel-active-task');let task=null;if(remembered){const detail=await json(`/api/tasks/${remembered}`);task=detail.task}else{const list=await json(`/api/tasks?novel=${enc(state.novel)}&limit=1`);if(list.tasks?.length)task=(await json(`/api/tasks/${list.tasks[0].id}`)).task}if(!task)return;state.activeTask=!['completed','failed','cancelled'].includes(task.status)?task.id:null;$('runtimeLog').innerHTML='';runtimeProgress(task.progress||0);runtimeLog(`${task.title} · ${task.status}`);(task.events||[]).slice(-20).forEach(item=>runtimeLog(item.message,item.level));if(task.status==='interrupted'){const resumable=['batch_chapters','workflow','import_rebuild','history_revision'].includes(task.kind);runtimeLog(resumable?'服务曾重启，此任务可从检查点恢复':'实时生成已因服务重启中断，请重新发起','warning')}}catch(error){console.warn('恢复任务中心失败',error)}}
let taskWatchTimer=null,lastTaskEvent=0;async function watchTask(taskId){state.activeTask=taskId;localStorage.setItem('novel-active-task',taskId);clearInterval(taskWatchTimer);const poll=async()=>{try{const detail=await json(`/api/tasks/${taskId}`),task=detail.task;runtimeProgress(task.progress||0);const events=(task.events||[]).filter(item=>item.id>lastTaskEvent);events.forEach(item=>{runtimeLog(item.message,item.level);lastTaskEvent=Math.max(lastTaskEvent,item.id)});if(['completed','failed','cancelled'].includes(task.status)){clearInterval(taskWatchTimer);state.activeTask=null;localStorage.removeItem('novel-active-task');runtimeLog(task.status==='completed'?'后台任务全部完成':`任务结束：${task.error||task.status}`,task.status==='completed'?'done':'error');if(task.status==='completed')toast('后台生成任务完成')}}catch(error){console.warn(error)}};await poll();taskWatchTimer=setInterval(poll,2000)}

const createWizard={step:0,source:{},plan:{},mode:'create'};
function installExtendedSourceFields(){if(!$('newWorld')||$('newProtagonist'))return;const label=$('newWorld').closest('label');label.querySelector('textarea').placeholder='只写尚未被下方结构化字段覆盖的补充想法';label.firstChild.textContent='其它补充说明';label.insertAdjacentHTML('afterend',`<div class="extended-source source-brief"><h3>故事发动机</h3><div class="two"><label>时代与主要舞台<input id="newSetting" placeholder="例：近未来海港城，社会被记忆评分系统控制"></label><label>叙事视角<input id="newViewpoint" placeholder="例：第三人称限知，主要跟随主角"></label></div><label>主角开局状态<textarea id="newProtagonist" rows="3" placeholder="身份、处境、已有能力、性格缺陷；不要只写‘普通人’"></textarea></label><div class="two"><label>主角外在目标<textarea id="newExternalGoal" rows="3" placeholder="故事中可以验证成败的具体目标"></textarea></label><label>主角内在缺口<textarea id="newInternalNeed" rows="3" placeholder="主角需要改变但自己尚未承认的问题"></textarea></label></div><div class="two"><label>主要对手与阻力<textarea id="newOpposition" rows="3" placeholder="谁或什么持续阻止主角，以及其合理动机"></textarea></label><label>失败代价<textarea id="newStakes" rows="3" placeholder="主角失败会具体失去什么；个人、关系和世界层面"></textarea></label></div><label>开篇触发事件<textarea id="newIncitingIncident" rows="3" placeholder="迫使主角离开原有生活、无法简单退出的具体事件"></textarea></label><h3>世界与剧情边界</h3><div class="two"><label>世界硬规则与边界<textarea id="newWorldRules" rows="3" placeholder="能力/技术/制度能做什么、不能做什么"></textarea></label><label>能力、资源与代价<textarea id="newPowerCost" rows="3" placeholder="主角优势、使用限制、消耗和反制方式"></textarea></label></div><label>核心谜团或长期问题<textarea id="newCoreQuestion" rows="3" placeholder="读者持续追问的问题；非悬疑题材也可写长期矛盾"></textarea></label><label>必须经过的关键节点<textarea id="newMilestones" rows="3" placeholder="只写少数不可缺少的事件或状态变化，不要提前写完整大纲"></textarea></label><div class="two"><label>必须出现或保留<textarea id="newMustHave" rows="3" placeholder="必须存在的体验、关系或元素"></textarea></label><label>绝对禁止出现<textarea id="newProhibited" rows="3" placeholder="不接受的套路、关系、设定和结局"></textarea></label></div><h3>阅读体验</h3><div class="two"><label>目标读者与情绪体验<input id="newAudience" placeholder="例：成年读者；压迫、紧张、偶尔黑色幽默"></label><label>节奏倾向<input id="newPacing" placeholder="例：开篇快，中段允许人物缓冲，卷末强高潮"></label></div><div class="two"><label>感情线与群像倾向<input id="newRelationshipLine" placeholder="无感情线 / 慢热单线 / 群像"></label><label>结局状态<input id="newEndingPreference" placeholder="写主角、关系和世界最终变成什么状态"></label></div></div>`)}
installExtendedSourceFields();
const wizardAiFields={newGenre:'genre',newTargetChapters:'target_chapters',newDescription:'description',newWorld:'notes',newSetting:'setting',newViewpoint:'viewpoint',newProtagonist:'protagonist',newExternalGoal:'external_goal',newInternalNeed:'internal_need',newOpposition:'opposition',newStakes:'stakes',newIncitingIncident:'inciting_incident',newWorldRules:'world_rules',newPowerCost:'power_cost',newCoreQuestion:'core_question',newMilestones:'milestones',newMustHave:'must_have',newProhibited:'prohibited',newAudience:'audience',newPacing:'pacing',newRelationshipLine:'relationship_line',newEndingPreference:'ending_preference',foundationPremise:'foundation_premise',foundationTheme:'foundation_theme',foundationWorld:'foundation_world',foundationRules:'foundation_rules',foundationStyle:'foundation_style',foundationEnding:'foundation_ending',structureOutline:'structure_outline',rollingPlan:'rolling_plan'};
function installWizardAiButtons(){Object.entries(wizardAiFields).forEach(([id,field])=>{const control=$(id);if(!control||control.parentElement.querySelector(`.field-ai[data-field="${field}"]`))return;const button=document.createElement('button');button.type='button';button.className='secondary field-ai';button.dataset.field=field;button.textContent=control.value.trim()?'AI 补全':'AI 生成';button.onclick=()=>generateWizardField(field,control,button);control.insertAdjacentElement('afterend',button)})}
function collectWizardAssistContext(){const context={};Object.entries(wizardAiFields).forEach(([id,field])=>{if($(id)?.value.trim())context[field]=$(id).value.trim()});context.name=$('newName')?.value.trim()||'';context.genre=$('newGenre')?.value.trim()||'';context.target_chapters=$('newTargetChapters')?.value||100;if(createWizard?.plan)context.accepted_plan=createWizard.plan;return context}
async function generateWizardField(field,control,button){const old=button.textContent;setBusy(button,true,'AI 生成中…');planLog(`正在单独推演：${control.closest('label')?.childNodes[0]?.textContent?.trim()||field}`,5);try{const data=await json(`/api/assist/source-field/${field}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(collectWizardAssistContext())});control.value=data.value;control.dispatchEvent(new Event('input'));button.textContent='AI 重新生成';planLog(`字段已生成 · ${data.metrics?.tokens_per_second||0} token/s`,10);saveWizardDraft()}catch(error){toast(error.message,true);button.textContent=old}finally{button.disabled=false}}
installWizardAiButtons();
function installStructuredAiButtons(){const fields={charactersJson:'characters',volumesJson:'structure',openingJson:'opening'};Object.entries(fields).forEach(([id,stage])=>{const control=$(id);if(!control||control.parentElement.querySelector(`[data-structured-stage="${stage}"]`))return;const button=document.createElement('button');button.type='button';button.className='secondary field-ai';button.dataset.structuredStage=stage;button.textContent='AI 重新生成结构';button.onclick=async()=>{setBusy(button,true,'AI 生成中…');try{if(stage==='structure'&&$('charactersJson').value)createWizard.plan.characters={characters:parseWizardJson('charactersJson','人物数据')};if(stage==='opening'&&$('volumesJson').value)createWizard.plan.structure={outline:$('structureOutline').value.trim(),volumes:parseWizardJson('volumesJson','分卷数据')};await generateWizardStage(stage)}catch(error){toast(error.message,true)}finally{setBusy(button,false,'AI 重新生成结构')}};control.insertAdjacentElement('afterend',button)})}
installStructuredAiButtons();
function installGenerateAllSourceButton(){const page=document.querySelector('.wizard-page[data-create-step="0"]');if(!page||$('generateAllSource'))return;const box=document.createElement('div');box.className='generate-all-source';box.innerHTML='<div><b>不知道怎样填写？</b><small>一次生成完整且彼此一致的创作简报，生成后仍可逐项修改。</small></div><button type="button" class="primary" id="generateAllSource">✦ 一键 AI 生成全部内容</button>';page.append(box);$('generateAllSource').onclick=generateAllSource}
async function generateAllSource(){const button=$('generateAllSource');setBusy(button,true,'正在生成完整简报…');planLog('正在一次性构建完整创作简报与故事种子，已有内容会作为硬约束',5);try{const context=collectWizardAssistContext();if($('newName').value.trim())context.name=$('newName').value.trim();const data=await json('/api/assist/source-all',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(context)}),source=data.source||{},mapping={name:'newName',genre:'newGenre',target_chapters:'newTargetChapters',description:'newDescription',notes:'newWorld',setting:'newSetting',viewpoint:'newViewpoint',protagonist:'newProtagonist',external_goal:'newExternalGoal',internal_need:'newInternalNeed',opposition:'newOpposition',stakes:'newStakes',inciting_incident:'newIncitingIncident',world_rules:'newWorldRules',power_cost:'newPowerCost',core_question:'newCoreQuestion',milestones:'newMilestones',must_have:'newMustHave',prohibited:'newProhibited',audience:'newAudience',pacing:'newPacing',relationship_line:'newRelationshipLine',ending_preference:'newEndingPreference'};Object.entries(mapping).forEach(([key,id])=>{if($(id)&&source[key]!==undefined){$(id).value=Array.isArray(source[key])?source[key].join('\n'):source[key]}});if(source.story_seed){$('storySeedJson').value=JSON.stringify(source.story_seed,null,2);$('storySeedJson').dataset.stale='0';createWizard.source.story_seed=source.story_seed}document.querySelectorAll('.field-ai').forEach(item=>item.textContent=item.dataset.structuredStage?'AI 重新生成结构':'AI 重新生成');await collectCreateSource();saveWizardDraft();planLog(`完整简报与故事种子已生成 · ${data.metrics?.tokens_per_second||0} token/s`,20);toast('全部内容已生成，可以检查故事种子后继续')}catch(error){toast(error.message,true);planLog(`完整简报生成失败：${error.message}`,5)}finally{setBusy(button,false,'✦ 一键 AI 生成全部内容')}}
installGenerateAllSourceButton();
function organizeSourceBrief(){const brief=document.querySelector('.source-brief');if(brief&&!brief.closest('details')){const details=document.createElement('details');details.className='source-details';details.innerHTML='<summary>高级创作访谈（可选展开逐项控制）</summary>';brief.before(details);details.append(brief)}const page=document.querySelector('.wizard-page[data-create-step="0"]');if(page&&!$('storySeedJson')){const section=document.createElement('section');section.className='story-seed-box';section.innerHTML='<div class="prompt-settings-head"><div><h3>AI 归纳后的故事种子</h3><p class="hint">后续策划只使用这份确认稿和硬约束，不再反复携带全部访谈原文。</p></div><button type="button" class="primary" id="summarizeSource">AI 归纳源数据</button></div><textarea id="storySeedJson" class="code-area" rows="14" placeholder="填写详细源数据后点击“AI 归纳源数据”；生成后可直接修改 JSON。"></textarea>';page.append(section);$('summarizeSource').onclick=summarizeSource}}
async function summarizeSource(){const button=$('summarizeSource');setBusy(button,true,'正在归纳…');try{await collectCreateSource();const rawSource={...createWizard.source};delete rawSource.story_seed;const data=await json('/api/assist/source-summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(rawSource)});$('storySeedJson').value=JSON.stringify(data.story_seed,null,2);$('storySeedJson').dataset.stale='0';createWizard.source.story_seed=data.story_seed;saveWizardDraft();planLog(`故事种子已归纳 · ${data.metrics?.tokens_per_second||0} token/s`,20);toast('请检查并修改故事种子，确认后再继续')}catch(error){toast(error.message,true)}finally{setBusy(button,false,'重新归纳源数据')}}
organizeSourceBrief();
function trackStorySeedFreshness(){Object.keys(wizardAiFields).filter(id=>id.startsWith('new')).forEach(id=>$(id)?.addEventListener('input',()=>{if($('storySeedJson')?.value.trim()){$('storySeedJson').dataset.stale='1';$('summarizeSource').textContent='源数据已变化，重新归纳';$('storySeedJson').classList.add('stale')}}));$('storySeedJson')?.addEventListener('input',()=>{$('storySeedJson').classList.remove('stale');$('storySeedJson').dataset.stale='0'})}
trackStorySeedFreshness();
const wizardDraftKey='novel-create-wizard-draft';
function saveWizardDraft(){if(createWizard.mode==='replan')return;localStorage.setItem(wizardDraftKey,JSON.stringify({step:createWizard.step,source:createWizard.source,plan:createWizard.plan}))}
function restoreWizardDraft(){try{const draft=JSON.parse(localStorage.getItem(wizardDraftKey)||'null');if(!draft)return false;createWizard.step=draft.step||0;createWizard.source=draft.source||{};createWizard.plan=draft.plan||{};const fields={name:'newName',genre:'newGenre',description:'newDescription',notes:'newWorld',setting:'newSetting',viewpoint:'newViewpoint',protagonist:'newProtagonist',external_goal:'newExternalGoal',internal_need:'newInternalNeed',opposition:'newOpposition',stakes:'newStakes',inciting_incident:'newIncitingIncident',world_rules:'newWorldRules',power_cost:'newPowerCost',core_question:'newCoreQuestion',milestones:'newMilestones',must_have:'newMustHave',prohibited:'newProhibited',audience:'newAudience',pacing:'newPacing',relationship_line:'newRelationshipLine',ending_preference:'newEndingPreference',target_chapters:'newTargetChapters'};Object.entries(fields).forEach(([key,id])=>{if(createWizard.source[key]!==undefined&&$(id))$(id).value=createWizard.source[key]});if(createWizard.source.story_seed&&$('storySeedJson'))$('storySeedJson').value=JSON.stringify(createWizard.source.story_seed,null,2);Object.entries(createWizard.plan).forEach(([stage,result])=>renderWizardStage(stage,result));showCreateStep(createWizard.step);return true}catch{return false}}
function showCreateStep(step){createWizard.step=step;document.querySelectorAll('.wizard-page').forEach(page=>page.classList.toggle('active',Number(page.dataset.createStep)===step));document.querySelectorAll('#createWizardTrack span').forEach((item,index)=>item.classList.toggle('active',index<=step));$('createPrev').style.display=step?'inline-block':'none';$('createRegenerate').style.display=step?'inline-block':'none';$('createNext').style.display=step<4?'inline-block':'none';$('createFinish').style.display=step===4?'inline-block':'none';$('createNext').textContent=['生成故事设定','确认设定并生成人物','确认人物并生成总纲','确认总纲并生成开篇细纲'][step]||'下一步'}
function resetCreateWizard(){createWizard.step=0;createWizard.source={};createWizard.plan={};createWizard.mode='create';[...Object.keys(wizardAiFields),'newName','charactersJson','volumesJson','openingJson','storySeedJson'].forEach(id=>{if($(id))$(id).value=''});$('newName').readOnly=false;$('newTargetChapters').value='100';$('newStyleReference').value='';$('planLog').innerHTML='';$('planConsole').classList.remove('show');$('createDialog').querySelector('h2').textContent='分阶段推演新小说';$('createFinish').textContent='确认并创建小说';document.querySelectorAll('.field-ai').forEach(button=>button.textContent='AI 生成');showCreateStep(0)}
document.querySelectorAll('[data-action="create"]').forEach(button=>button.onclick=()=>{if(!restoreWizardDraft())resetCreateWizard();createWizard.mode='create';$('newName').readOnly=false;$('createDialog').querySelector('h2').textContent='分阶段推演新小说';$('createFinish').textContent='确认并创建小说';$('createDialog').showModal()});
