$('settingsBtn')?.addEventListener('click',async()=>{try{const [data,promptData,modelStatus]=await Promise.all([json('/api/settings'),json('/api/settings/prompts'),json('/api/model/status')]),settings=data.settings,profiles=data.model.sampling_profiles||{},profileText=Object.entries(profiles).map(([name,p])=>`${name}: T${p.temperature} · P${p.top_p} · K${p.top_k} · Repeat${p.repeat_penalty} · Presence${p.presence_penalty}`).join('\n');$('settingWords').value=settings.default_target_words;$('settingBatch').value=settings.default_batch_chapters;$('settingStopWarning').checked=settings.stop_batch_on_warning;$('settingDraft').checked=settings.auto_save_drafts;$('settingWarmup').checked=settings.auto_warmup;$('settingCreativity').value=settings.creativity_mode||'balanced';$('settingCommitMode').value=settings.chapter_commit_mode||'balanced';$('settingSpeedRatio').value=String(settings.speed_warning_ratio||.7);$('modelSettingsInfo').textContent=`模型：${data.model.model}\n上下文：${data.model.context_window}\n有效输入预算：${data.model.available_context}\n并发：1（硬件安全锁定）\n\n任务采样档案\n${profileText}`;renderModelManager(modelStatus,settings);renderPerformancePanel(modelStatus);renderPromptSettings(promptData.prompts);$('settingsDialog').showModal()}catch(error){toast(error.message,true)}});
$('saveSettings')?.addEventListener('click',async()=>{try{const [response,promptResponse]=await Promise.all([fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({default_target_words:Number($('settingWords').value),default_batch_chapters:Number($('settingBatch').value),stop_batch_on_warning:$('settingStopWarning').checked,auto_save_drafts:$('settingDraft').checked,auto_warmup:$('settingWarmup').checked,creativity_mode:$('settingCreativity').value,chapter_commit_mode:$('settingCommitMode').value,speed_warning_ratio:Number($('settingSpeedRatio').value),seed_mode:$('settingSeedMode')?.value||'random',fixed_seed:Number($('settingFixedSeed')?.value||42)})}),fetch('/api/settings/prompts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(collectPromptSettings())})]),result=await response.json(),promptResult=await promptResponse.json();if(!response.ok||!result.success)throw new Error(result.error||'保存失败');if(!promptResponse.ok||!promptResult.success)throw new Error(promptResult.error||'提示词保存失败');if($('targetWords'))$('targetWords').value=String(result.settings.default_target_words);if($('batchCount'))$('batchCount').value=result.settings.default_batch_chapters;if($('batchWords'))$('batchWords').value=result.settings.default_target_words;if($('batchStopWarning'))$('batchStopWarning').checked=result.settings.stop_batch_on_warning;$('settingsDialog').close();toast('设置和提示词已保存')}catch(error){toast(error.message,true)}});
