document.querySelectorAll('#tabs button').forEach(button=>button.onclick=()=>openTab(button.dataset.tab));
async function openTab(name){document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===`panel-${name}`));try{if(name==='dashboard'){await Promise.all([loadDashboard(),loadReviewQueue()]);await loadProductionCenter()}if(name==='story')await loadBible();if(name==='characters'){await loadCharacters();await loadRelationshipGraph()}if(name==='chapters')await loadChapters();if(name==='timeline'){await loadTimeline();await loadStoryLogic();await loadCausalGraph();initCausalRepairTool();await loadPlanningReviews();await loadVolumeReviews();await loadEntities()}}catch(error){toast(error.message,true)}}
async function loadDashboard(){
 const result=await json(`/api/novels/${enc(state.novel)}/dashboard`),data=result.dashboard,position=data.planning_position||{},stats=[['当前章节',data.state.current_chapter||0],['目标章节',data.state.target_chapters||'未设定'],['当前卷',position.volume||'未规划'],['当前节',position.section||'未规划'],['节纲进度',(position.section_progress||0)+'%'],['总字数',(data.state.total_words||0).toLocaleString()],['人物',data.character_count],['待确认人物变化',data.pending_character_changes,data.pending_character_changes>0],['硬事实冲突',data.fact_conflicts,data.fact_conflicts>0],['开放伏笔',data.open_foreshadows],['超期伏笔',data.overdue_foreshadows,data.overdue_foreshadows>0],['质量待办',data.quality.pending,data.quality.pending>0]];
 $('dashboardStats').innerHTML=stats.map(item=>`<article class="dashboard-stat ${item[2]?'warn':''}"><small>${item[0]}</small><b>${item[1]}</b></article>`).join('');
 const tasks=data.tasks||[],resumableKinds=new Set(['batch_chapters','workflow','import_rebuild','history_revision']);
 $('dashboardTasks').innerHTML=tasks.map(task=>`<div class="chapter-row task-row"><div><b>${escapeHtml(task.title)}</b><small>${escapeHtml(task.status)} · ${task.progress}% · ${escapeHtml(task.stage||'')}${task.error?' · '+escapeHtml(task.error):''}</small></div><span><button type="button" class="secondary task-view" data-id="${task.id}">日志</button>${['paused','failed','interrupted'].includes(task.status)&&resumableKinds.has(task.kind)?` <button type="button" class="primary task-resume" data-id="${task.id}">恢复</button>`:''}${['queued','running','paused','interrupted'].includes(task.status)?` <button type="button" class="secondary task-cancel" data-id="${task.id}">取消</button>`:''}</span></div>`).join('')||'<p class="hint">暂无任务记录</p>';
 $('dashboardTasks').querySelectorAll('.task-view').forEach(button=>button.onclick=()=>showTaskLog(button.dataset.id));
 $('dashboardTasks').querySelectorAll('.task-resume').forEach(button=>button.onclick=async()=>{try{try{await post(`/api/tasks/${button.dataset.id}/resume`,{})}catch(error){if(!String(error.message).includes('必须明确批准')||!confirm(`${error.message}\n\n批准表示接受日志中列出的质量、设定、时空或规划例外，并继续自动连载。确定吗？`))throw error;await post(`/api/tasks/${button.dataset.id}/resume`,{approve_review:true})}toast('任务已批准并重新排队');watchTask(button.dataset.id);await Promise.all([loadDashboard(),loadReviewQueue()])}catch(error){toast(error.message,true)}});
 $('dashboardTasks').querySelectorAll('.task-cancel').forEach(button=>button.onclick=async()=>{if(!confirm('取消这个任务？已提交正史的章节不会回滚。'))return;try{await post(`/api/tasks/${button.dataset.id}/cancel`,{});toast('任务已取消');await loadDashboard()}catch(error){toast(error.message,true)}})
}
async function showTaskLog(taskId){try{const data=await json(`/api/tasks/${taskId}`),task=data.task||{},dialog=ensureUtilityDialog('taskLogDialog','后台任务日志');dialog.querySelector('.utility-dialog-body').innerHTML=`<div class="chapter-row"><b>${escapeHtml(task.title||'任务')}</b><small>${escapeHtml(task.status||'')} · ${task.progress||0}%</small></div><div class="runtime-log task-log-static">${(task.events||[]).map(item=>`<p class="${escapeHtml(item.level||'info')}"><time>${escapeHtml(item.created_at||'')}</time> ${escapeHtml(item.message||'')}</p>`).join('')||'<p class="hint">暂无日志</p>'}</div>`;dialog.showModal()}catch(error){toast(error.message,true)}}
$('refreshDashboard')?.addEventListener('click',()=>Promise.all([loadDashboard(),loadReviewQueue()]));

async function loadReviewQueue(){if(!$('reviewQueueList'))return;const [queue,locks,clock]=await Promise.all([json(`/api/novels/${enc(state.novel)}/review-queue`),json(`/api/novels/${enc(state.novel)}/canonical-locks`),json(`/api/novels/${enc(state.novel)}/story-clock`)]);$('reviewQueueStats').innerHTML=[['待处理',queue.total||0],['阻断自动连载',queue.blocking||0],['设定锁',(locks.items||[]).length],['故事时钟事件',(clock.clock?.events||[]).length]].map(item=>`<article class="dashboard-stat ${item[0]==='阻断自动连载'&&item[1]?'warn':''}"><small>${item[0]}</small><b>${item[1]}</b></article>`).join('');$('reviewQueueList').innerHTML=(queue.items||[]).slice(0,60).map(item=>`<div class="chapter-row review-queue-item" data-target="${escapeHtml(item.target||'dashboard')}"><div><b>${item.blocking?'⛔':'△'} ${escapeHtml(item.title)}${item.chapter?` · 第${item.chapter}章`:''}</b><small>${escapeHtml(item.detail||'')} · ${escapeHtml(item.severity)}风险</small></div><button type="button" class="secondary">前往处理</button></div>`).join('')||'<p class="hint">当前没有待审核事项。</p>';$('reviewQueueList').querySelectorAll('.review-queue-item').forEach(row=>row.onclick=()=>openTab(row.dataset.target));$('canonicalLockList').innerHTML=(locks.items||[]).map(item=>`<div class="chapter-row"><div><b>${escapeHtml(item.kind)} / ${escapeHtml(item.name)} / ${escapeHtml(item.field)}</b><small>${escapeHtml(item.value)}${item.reason?' · '+escapeHtml(item.reason):''}</small></div><button type="button" class="secondary remove-lock" data-id="${item.id}">解除</button></div>`).join('')||'<p class="hint">尚未设置权威锁。</p>';$('canonicalLockList').querySelectorAll('.remove-lock').forEach(button=>button.onclick=async()=>{if(!confirm('解除这条权威设定锁？'))return;await json(`/api/novels/${enc(state.novel)}/canonical-locks/${button.dataset.id}`,{method:'DELETE'});await loadReviewQueue()});$('travelRuleList').innerHTML=(clock.clock?.travel_rules||[]).map(item=>`<div class="chapter-row"><div><b>${escapeHtml(item.from)} ↔ ${escapeHtml(item.to)}</b><small>至少 ${item.minutes} 分钟</small></div><button type="button" class="secondary remove-travel" data-from="${escapeHtml(item.from)}" data-to="${escapeHtml(item.to)}">删除</button></div>`).join('')||'<p class="hint">尚未设置地点移动耗时。</p>';$('travelRuleList').querySelectorAll('.remove-travel').forEach(button=>button.onclick=async()=>{if(!confirm('删除这条移动耗时规则？'))return;await json(`/api/novels/${enc(state.novel)}/story-clock/travel-rules?origin=${enc(button.dataset.from)}&destination=${enc(button.dataset.to)}`,{method:'DELETE'});await loadReviewQueue()})}
$('addCanonicalLock')?.addEventListener('click',async()=>{try{await json(`/api/novels/${enc(state.novel)}/canonical-locks`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:$('lockKind').value,name:$('lockName').value,field:$('lockField').value,value:$('lockValue').value,reason:$('lockReason').value})});toast('权威设定锁已保存');await loadReviewQueue()}catch(error){toast(error.message,true)}});
$('addTravelRule')?.addEventListener('click',async()=>{try{await json(`/api/novels/${enc(state.novel)}/story-clock/travel-rules`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({from:$('travelFrom').value,to:$('travelTo').value,minutes:Number($('travelMinutes').value)})});toast('移动规则已保存');await loadReviewQueue()}catch(error){toast(error.message,true)}});

async function readStyleReference(){const file=$('newStyleReference')?.files[0];if(!file)return'';if(file.size>2_000_000)throw new Error('文风参考文件不能超过2MB');const text=await file.text();return text.slice(0,30000)}
async function collectCreateSource(){const name=$('newName').value.trim(),target=Math.max(5,Math.min(1000,Number($('newTargetChapters').value)||100));if(!name)throw new Error('请填写书名');if(!$('newDescription').value.trim())throw new Error('请填写核心创意');const ids={setting:'newSetting',viewpoint:'newViewpoint',protagonist:'newProtagonist',external_goal:'newExternalGoal',internal_need:'newInternalNeed',opposition:'newOpposition',stakes:'newStakes',inciting_incident:'newIncitingIncident',world_rules:'newWorldRules',power_cost:'newPowerCost',core_question:'newCoreQuestion',milestones:'newMilestones',must_have:'newMustHave',prohibited:'newProhibited',audience:'newAudience',pacing:'newPacing',relationship_line:'newRelationshipLine',ending_preference:'newEndingPreference'};createWizard.source={name,genre:$('newGenre').value.trim(),description:$('newDescription').value.trim(),notes:$('newWorld').value.trim(),target_chapters:target,style_reference:await readStyleReference()};Object.entries(ids).forEach(([key,id])=>createWizard.source[key]=$(id)?.value.trim()||'');const missing=[['protagonist','主角开局状态'],['external_goal','主角外在目标'],['opposition','主要对手与阻力'],['stakes','失败代价'],['inciting_incident','开篇触发事件']].filter(([key])=>!createWizard.source[key]).map(([,label])=>label);if(missing.length)throw new Error('请至少填写：'+missing.join('、'));if($('storySeedJson')?.value.trim())createWizard.source.story_seed=parseWizardJson('storySeedJson','故事种子')}
function parseWizardJson(id,label){try{return JSON.parse($(id).value)}catch{throw new Error(`${label}不是有效JSON，请检查逗号和引号`)}}
function collectWizardStep(step=createWizard.step){if(step===1)createWizard.plan.foundation={premise:$('foundationPremise').value.trim(),theme:$('foundationTheme').value.trim(),world:$('foundationWorld').value.trim(),rules:$('foundationRules').value.trim(),style:$('foundationStyle').value.trim(),ending_direction:$('foundationEnding').value.trim()};if(step===2)createWizard.plan.characters={characters:parseWizardJson('charactersJson','人物数据')};if(step===3)createWizard.plan.structure={outline:$('structureOutline').value.trim(),volumes:parseWizardJson('volumesJson','分卷数据')};if(step===4){const opening=parseWizardJson('openingJson','章节细纲');createWizard.plan.opening={chapters:Array.isArray(opening)?opening:opening.chapters,rolling_plan:$('rollingPlan').value.trim()}}}
function renderWizardStage(stage,result){if(stage==='foundation'){ $('foundationPremise').value=result.premise||'';$('foundationTheme').value=result.theme||'';$('foundationWorld').value=result.world||'';$('foundationRules').value=result.rules||'';$('foundationStyle').value=result.style||'';$('foundationEnding').value=result.ending_direction||''}if(stage==='characters')$('charactersJson').value=JSON.stringify(result.characters||[],null,2);if(stage==='structure'){$('structureOutline').value=result.outline||'';$('volumesJson').value=JSON.stringify(result.volumes||[],null,2)}if(stage==='opening'){$('openingJson').value=JSON.stringify(result.chapters||[],null,2);$('rollingPlan').value=result.rolling_plan||''}saveWizardDraft()}
async function generateWizardStage(stage){const labels={foundation:'故事设定',characters:'主要人物',structure:'总纲与分卷',opening:'开篇章节细纲'},hadStyleReference=stage==='foundation'&&Boolean(createWizard.source.style_reference);if(hadStyleReference)planLog('正在隔离分析文风，只提取表达参数…',8);planLog(`正在推演${labels[stage]}…`,createWizard.step*20+10);const response=await fetch(`/api/planning/stage/${stage}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:createWizard.source,accepted:createWizard.plan})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'推演失败');if(data.style_profile)createWizard.source.style_profile=data.style_profile;if(hadStyleReference){delete createWizard.source.style_reference;planLog('文风原文已丢弃，后续仅使用抽象风格参数',15)}createWizard.plan[stage]=data.result;renderWizardStage(stage,data.result);if(stage==='characters'&&data.result.personality_diversity?.status==='warning'){const diversity=data.result.personality_diversity,pairs=diversity.similar_pairs||[],incomplete=diversity.incomplete_profiles||[],messages=[];if(pairs.length)messages.push(`过于相似：${pairs.map(item=>`${item.left}/${item.right}`).join('、')}`);if(incomplete.length)messages.push(`指纹不完整：${incomplete.map(item=>`${item.name}(${item.filled_fields}/9)`).join('、')}`);planLog(`人物人格需要复核：${messages.join('；')}。建议补充欲望、缺点、受压反应和决策方式`,Math.min(94,(createWizard.step+1)*20),'warning')}const speed=data.metrics?.tokens_per_second||0,tokens=data.metrics?.completion_tokens||0;planLog(`${labels[stage]}已生成 · ${speed} token/s · ${tokens} tokens`,Math.min(95,(createWizard.step+1)*20));return data.result}
$('createNext')?.addEventListener('click',async()=>{setBusy($('createNext'),true,'推演中…');try{if(createWizard.step===0){await collectCreateSource();if(!createWizard.source.story_seed||$('storySeedJson')?.dataset.stale==='1'){await summarizeSource();return}}else collectWizardStep();const stages=['foundation','characters','structure','opening'],stage=stages[createWizard.step];await generateWizardStage(stage);showCreateStep(createWizard.step+1)}catch(error){toast(error.message,true);planLog(`失败：${error.message}`,createWizard.step*20)}finally{setBusy($('createNext'),false);showCreateStep(createWizard.step)}});
$('createPrev')?.addEventListener('click',()=>{try{collectWizardStep()}catch{}showCreateStep(Math.max(0,createWizard.step-1))});
$('createRegenerate')?.addEventListener('click',async()=>{const stages=['','foundation','characters','structure','opening'],stage=stages[createWizard.step];if(!stage)return;setBusy($('createRegenerate'),true,'重新生成中…');try{await generateWizardStage(stage)}catch(error){toast(error.message,true)}finally{setBusy($('createRegenerate'),false,'重新生成本步')}});
$('createFinish')?.addEventListener('click',async()=>{const replanning=createWizard.mode==='replan';setBusy($('createFinish'),true,replanning?'正在应用…':'正在创建…');try{collectWizardStep(4);const url=replanning?`/api/novels/${enc(state.novel)}/apply-staged-plan`:'/api/novels/create-from-plan',response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:createWizard.source,plan:createWizard.plan})}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||(replanning?'应用失败':'创建失败'));localStorage.removeItem(wizardDraftKey);toast(replanning?`分阶段策划已应用，目标${data.target_chapters}章`:`小说已创建，目标${data.target_chapters}章`);setTimeout(()=>location.reload(),500)}catch(error){toast(error.message,true)}finally{setBusy($('createFinish'),false,replanning?'确认并应用策划':'确认并创建小说')}});
document.querySelectorAll('.ai-create').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const result=await post('/api/assist/title',{genre:$('newGenre').value,idea:$('newDescription').value});$('newName').value=result.content}catch(error){toast(error.message,true)}finally{button.disabled=false}});

const editor=$('editor');editor?.addEventListener('input',()=>{$('editorWords').textContent=`${editor.value.replace(/\s/g,'').length} 字`});
if(editor&&state.novel){const draftKey=`novel-draft:${state.novel}`;const draft=localStorage.getItem(draftKey);if(draft&&!editor.value){editor.value=draft;editor.dispatchEvent(new Event('input'));$('generationStatus').textContent='已恢复上次未保存草稿'}let draftTimer;editor.addEventListener('input',()=>{clearTimeout(draftTimer);if(state.settings.auto_save_drafts)draftTimer=setTimeout(()=>localStorage.setItem(draftKey,editor.value),500)})}
$('temperature')?.addEventListener('input',event=>$('tempOut').textContent=event.target.value);
$('topP')?.addEventListener('input',event=>$('topPOut').textContent=event.target.value);
$('clearBtn')?.addEventListener('click',()=>{if(editor.value&&!confirm('确定清空编辑器？'))return;editor.value='';state.editing=0;editor.dispatchEvent(new Event('input'));updateChapterLabel()});
let editSelection=null;document.querySelectorAll('.selection-edit').forEach(button=>button.onclick=async()=>{const start=editor.selectionStart,end=editor.selectionEnd,text=editor.value.slice(start,end);if(!text.trim())return toast('请先在正文中选中一段文字',true);setBusy(button,true,'处理中…');runtimeLog(`局部编辑：${button.textContent}`);try{const result=await post(`/api/novels/${enc(state.novel)}/edit-selection`,{text,operation:button.dataset.operation});if(result.metrics)runtimeLog(`局部编辑完成 · ${result.metrics.tokens_per_second} token/s · ${result.metrics.completion_tokens} tokens`);editSelection={start,end};$('editOriginal').value=text;$('editRevised').value=result.content;$('editCompareDialog').showModal()}catch(error){toast(error.message,true)}finally{setBusy(button,false,button.dataset.operation==='polish'?'润色选中':button.dataset.operation==='expand'?'扩写':button.dataset.operation==='dialogue'?'增强对话':'降低AI味')}});
if(editor&&!$('rewriteScene')){const button=document.createElement('button');button.id='rewriteScene';button.className='secondary';button.textContent='重写场景';document.querySelector('.editor-head>div:last-child')?.prepend(button);button.onclick=async()=>{const start=editor.selectionStart,end=editor.selectionEnd,scene=editor.value.slice(start,end);if(!scene.trim())return toast('请先选中一个完整场景',true);const instruction=prompt('希望怎样重写这个场景？','增强场景目标、阻力、人物互动和状态变化');if(instruction===null)return;setBusy(button,true,'场景重写中…');runtimeLog('正在局部重写选中场景');try{const result=await post(`/api/novels/${enc(state.novel)}/rewrite-scene`,{chapter:state.editing||state.chapter+1,scene,instruction,target_words:Math.max(500,scene.replace(/\s/g,'').length)});editSelection={start,end};$('editOriginal').value=scene;$('editRevised').value=result.content;$('editCompareDialog').showModal()}catch(error){toast(error.message,true)}finally{setBusy(button,false,'重写场景')}}}
$('applyEdit')?.addEventListener('click',()=>{if(!editSelection)return;editor.setRangeText($('editRevised').value,editSelection.start,editSelection.end,'end');editor.dispatchEvent(new Event('input'));$('editCompareDialog').close();editSelection=null;toast('已采用修改稿')});
$('generateBtn')?.addEventListener('click',()=>generate(false));
$('continueBtn')?.addEventListener('click',()=>generate(true));
$('batchBtn')?.addEventListener('click',()=>$('batchDialog').showModal());
$('startBatch')?.addEventListener('click',async()=>{const count=Math.max(1,Math.min(10,Number($('batchCount').value)||3)),targetWords=Math.max(500,Math.min(20000,Number($('batchWords').value)||5000));setBusy($('startBatch'),true,'正在入队…');try{const result=await post(`/api/novels/${enc(state.novel)}/batch-generate`,{count,target_words:targetWords,stop_on_warning:$('batchStopWarning').checked});$('batchDialog').close();$('runtimeLog').innerHTML='';$('runtime').classList.add('show');lastTaskEvent=0;runtimeLog(`连续生成 ${count} 章已进入后台队列`);watchTask(result.task_id);toast('后台任务已创建，可以关闭或刷新页面')}catch(error){toast(error.message,true)}finally{setBusy($('startBatch'),false,'加入后台队列')}});
async function generate(continueExisting){if(state.generating)return;state.generating=true;state.controller=new AbortController();const started=Date.now(),target=Number($('targetWords').value),button=continueExisting?$('continueBtn'):$('generateBtn');setBusy(button,true,'正在生成…');$('runtimeLog').innerHTML='';runtimeProgress(4);runtimeLog('任务已创建，正在准备小说记忆');$('generationStatus').textContent='准备上下文';try{const context=await post(`/api/novels/${enc(state.novel)}/continue-story`,{}),health=context.context_health||{};runtimeProgress(15);runtimeLog(`上下文准备完成 · ${context.context_tokens||0} tokens · 最近正文 ${health.recent_full_chapters||0}章`);runtimeLog(`上下文健康度 ${health.usage_percent||0}% · ${health.health==='red'?'接近上限':health.health==='yellow'?'负载较高':'余量充足'}`,health.health==='red'?'warning':'token');if((health.segments||[]).length)runtimeLog(`上下文占用：${health.segments.slice(0,5).map(item=>`${item.label} ${item.tokens}t`).join(' · ')}`,'token');if(health.continuity_handoff)runtimeLog('已装载上一章连续性交接与正文证据','token');const goal=$('chapterGoal').value.trim();const existing=continueExisting?editor.value.trim():'';if(!continueExisting){editor.value='';state.editing=context.next_chapter||state.chapter+1;updateChapterLabel()}const direction=[context.context||'',goal?`\n【本章创作目标】\n${goal}`:'',existing?`\n【已经写好的正文，请紧接着续写，不要重复】\n${existing.slice(-8000)}`:''].join('');runtimeLog('正在连接本地 35B 模型');$('generationStatus').textContent='本地模型正在逐字创作';const response=await fetch(`/api/novels/${enc(state.novel)}/generate`,{method:'POST',body:form({context:direction,target_words:target,continuation:continueExisting,temperature:$('temperature').value,top_p:$('topP').value,top_k:20,repeat_penalty:1.08,presence_penalty:0}),signal:state.controller.signal});let generated=0,lastReport=0,qualityWarnings=[],qualityStatus='';await readEventStream(response,data=>{if(data.error)throw new Error(data.error);if(data.type==='replace'&&typeof data.content==='string'){editor.value=data.content;generated=data.content.replace(/\s/g,'').length;editor.dispatchEvent(new Event('input'));editor.scrollTop=editor.scrollHeight}if(data.type==='stage'&&data.message){runtimeLog(data.message);$('generationStatus').textContent=data.message}if(data.quality){qualityWarnings=data.quality.warnings||[];qualityStatus=data.quality.status||'';runtimeLog(`质量闸门：${qualityStatus} · ${data.quality.word_count||generated}/${data.quality.target_words||target}字`,qualityStatus==='PASS'?'token':'warning');qualityWarnings.forEach(item=>runtimeLog(`质量提醒：${item}`,'warning'))}if(data.token){editor.value+=data.token;generated+=data.token.replace(/\s/g,'').length;editor.dispatchEvent(new Event('input'));editor.scrollTop=editor.scrollHeight;const progress=Math.min(94,18+generated/target*76);runtimeProgress(progress);if(generated-lastReport>=200){const seconds=Math.max(1,(Date.now()-started)/1000);runtimeLog(`正在打字 · ${generated} 字 · ${(generated/seconds).toFixed(1)} 字/秒`,'token');lastReport=generated}}});runtimeProgress(100);generated=editor.value.replace(/\s/g,'').length;runtimeLog(`正文生成完成 · ${generated} 字 · ${Math.round((Date.now()-started)/1000)} 秒`);$('generationStatus').textContent=qualityStatus==='PASS'?'生成完成，质量检查通过':`生成完成 · ${qualityStatus||'请复核'}`;toast(qualityStatus==='PASS'?'章节生成完成':`生成完成，质量状态 ${qualityStatus||'WARNING'}`,qualityStatus!=='PASS')}catch(error){const message=error.name==='AbortError'?'任务已停止':error.message;runtimeLog(`生成结束：${message}`,'error');$('generationStatus').textContent=message;toast(message,true)}finally{state.controller=null;state.generating=false;setBusy(button,false,continueExisting?'根据现有内容续写':'✦ AI 生成下一章')}}
function updateChapterLabel(){const chapter=state.editing||state.chapter+1;$('editorChapter').textContent=`第 ${chapter} 章`}
async function saveChapterWithGovernance(payload){const approvals={},checks=[['硬事实','allow_fact_conflicts'],['权威设定锁','allow_locked_changes'],['故事时空','allow_story_clock_conflicts'],['人物决策','allow_character_decision_conflicts'],['结构化摘要','allow_degraded_summary']];for(let attempt=0;attempt<7;attempt++){try{return await post(`/api/novels/${enc(state.novel)}/chapters/save`,{...payload,...approvals})}catch(error){const message=String(error.message||''),match=checks.find(([text,key])=>message.includes(text)&&!approvals[key]),key=match?.[1]||'';if(!key||!confirm(`${message}\n\n这是高风险例外。确认理解影响并继续保存吗？`))throw error;approvals[key]=true}}throw new Error('治理检查未能完成，请从审核队列处理冲突')}
$('saveBtn')?.addEventListener('click',async()=>{const content=editor.value.trim();if(!content)return toast('正文还是空的',true);const chapter=state.editing||state.chapter+1,targetWords=Number($('targetWords').value)||5000;setBusy($('saveBtn'),true,'保存中…');runtimeLog(`开始保存第 ${chapter} 章`);runtimeProgress(20);try{const result=await saveChapterWithGovernance({chapter,content,target_words:targetWords});runtimeProgress(100);runtimeLog(`保存完成 · 质量闸门 ${result.quality?.status||'已检查'} · 摘要、人物变化与时间线已整理`,result.quality?.status==='PASS'?'token':'warning');const metrics=result.quality?.metrics;if(metrics)runtimeLog(`轻量质量：追读力 ${metrics.reader_pull} · 人味 ${metrics.human_texture} · 对话 ${Math.round(metrics.dialogue_ratio*100)}% · 动作密度 ${metrics.action_density}`,'token');state.chapter=Math.max(state.chapter,chapter);state.editing=chapter;$('chapterCount').textContent=state.chapter;$('generationStatus').textContent=`已保存 · ${result.quality?.status||'质量已检查'}`;toast(`第 ${chapter} 章已保存`);Promise.all([loadProductionCenter(),loadReviewQueue()]).catch(console.warn)}catch(error){runtimeLog(`保存失败：${error.message}`,'error');toast(error.message,true)}finally{setBusy($('saveBtn'),false,'保存章节')}});
async function refreshWritingContext(showToast=false){const data=await json(`/api/novels/${enc(state.novel)}/status`);$('chapterGoal').value=data.status?.next_goal||'';if($('currentChapterBrief'))$('currentChapterBrief').textContent=data.next_brief?`${data.next_brief.title||''}：${data.next_brief.synopsis||''}`:'生成章节时会先根据卷纲与节纲生成提要';if(showToast)toast('创作上下文已刷新')}
$('refreshContext')?.addEventListener('click',async()=>{try{await refreshWritingContext(true)}catch(error){toast(error.message,true)}});

function renderPlanningCards(volumes){const panel=$('panel-story');let box=$('planningCards');if(!box){box=document.createElement('div');box.id='planningCards';panel.insertBefore(box,$('storyVolumes'))}box.innerHTML=(volumes||[]).map((volume,index)=>`<article class="planning-card"><header><div><small>第${volume.start_chapter||'?'}—${volume.end_chapter||'?'}章</small><h3>${escapeHtml(volume.title||'未命名卷')}</h3></div><span>${(volume.sections||[]).length} 个节纲</span></header><p>${escapeHtml(volume.goal||volume.conflict||'尚未填写本卷目标')}</p><div class="planning-sections">${(volume.sections||[]).map(section=>`<div><b>${escapeHtml(section.title||'未命名节')}</b><small>第${section.start_chapter||'?'}—${section.end_chapter||'?'}章</small><p>${escapeHtml(section.purpose||section.outcome||'')}</p></div>`).join('')}</div></article>`).join('')||'<p class="hint">还没有分卷规划。</p>'}
async function loadBible(){const data=await json(`/api/novels/${enc(state.novel)}/bible`);$('world').value=data.bible.world||'';$('rules').value=data.bible.rules||'';$('style').value=data.bible.style||'';$('outline').value=data.bible.outline||'';$('storyTargetChapters').value=data.bible.target_chapters||100;$('storyVolumes').value=JSON.stringify(data.bible.volumes||[],null,2);$('storyBriefs').value=JSON.stringify(data.bible.chapter_briefs||{},null,2);renderPlanningCards(data.bible.volumes||[])}
async function openStagedReplan(){if(!confirm('将按故事设定、人物、总纲分卷、开篇细纲四步重新推演；每一步都可修改，最终确认前不会改变当前小说。继续吗？'))return;setBusy($('rerunPlan'),true,'准备中…');try{const [data,characterData]=await Promise.all([json(`/api/novels/${enc(state.novel)}/bible`),json(`/api/novels/${enc(state.novel)}/characters`)]),bible=data.bible||{},characters=characterData.characters||[],protagonist=characters.find(item=>item.role_tier==='主角')||characters[0]||{};resetCreateWizard();createWizard.mode='replan';const description=bible.description||String(bible.outline||'').slice(0,1200)||'依据当前设定重新整理长篇主线',protagonistText=protagonist.name?`${protagonist.name}：${protagonist.background||protagonist.personality||'沿用现有人物档案'}`:'依据当前设定确认主角开局';const values={newName:state.novel,newGenre:bible.genre||'',newTargetChapters:bible.target_chapters||100,newDescription:description,newWorld:'保留已经确认的硬设定；重策划结果分阶段确认后再应用',newSetting:bible.world||'',newViewpoint:'沿用当前文风与叙事视角',newProtagonist:protagonistText,newExternalGoal:bible.next_goal||'依据当前总纲明确可验证的长期目标',newInternalNeed:'依据现有人物弧提炼需要改变的内在缺口',newOpposition:'依据当前总纲重建持续且动机合理的主要阻力',newStakes:'保持现有事实，明确个人、关系与世界层面的失败代价',newIncitingIncident:'沿用当前开篇因果，不覆盖已经提交的正文',newWorldRules:bible.rules||'',newPowerCost:'从当前世界规则中提炼能力边界、消耗与反制',newCoreQuestion:'依据当前主线提炼贯穿全书的长期问题',newMilestones:'保留已发生事实，重新规划未来少数关键节点',newMustHave:'已提交正史、现有人物核心身份与世界硬规则',newProhibited:'不得让新规划否定已提交正史；不得混入文风参考剧情',newAudience:'长篇连续性、人物选择与因果推进',newPacing:'主线推进与人物、铺垫、余波章节交替',newRelationshipLine:'沿用已建立关系，未来变化必须有事件依据',newEndingPreference:'主线矛盾得到明确结果，选择产生不可逆后果'};Object.entries(values).forEach(([id,value])=>{if($(id))$(id).value=value});const seed={logline:description,protagonist_engine:protagonistText,conflict_engine:`${values.newOpposition}；${values.newStakes}`,world_contract:String(bible.rules||bible.world||'').slice(0,1800),long_question:values.newCoreQuestion,milestones:[values.newMilestones],experience_contract:`${values.newViewpoint}；${values.newPacing}`,ending_state:values.newEndingPreference,must_keep:[values.newMustHave],must_avoid:[values.newProhibited],open_space:['未来章节的具体场景、配角行动与局部转折']};$('storySeedJson').value=JSON.stringify(seed,null,2);$('storySeedJson').dataset.stale='0';createWizard.source={name:state.novel,genre:values.newGenre,description,target_chapters:Number(values.newTargetChapters),story_seed:seed};$('newName').readOnly=true;$('createDialog').querySelector('h2').textContent='分阶段重策划当前小说';$('createFinish').textContent='确认并应用策划';showCreateStep(0);$('createDialog').showModal()}catch(error){toast(error.message,true)}finally{setBusy($('rerunPlan'),false,'AI 分阶段重策划')}}
