$('saveBible')?.addEventListener('click',async()=>{try{JSON.parse($('storyVolumes').value||'[]');JSON.parse($('storyBriefs').value||'{}');await post(`/api/novels/${enc(state.novel)}/bible/save`,{world:$('world').value,rules:$('rules').value,style:$('style').value,outline:$('outline').value,next_goal:$('chapterGoal').value,target_chapters:$('storyTargetChapters').value,volumes:$('storyVolumes').value,chapter_briefs:$('storyBriefs').value});toast('故事设定与层级规划已保存')}catch(error){toast(`保存失败：${error.message}`,true)}});

async function loadCharacters(){const [data,reviews]=await Promise.all([json(`/api/novels/${enc(state.novel)}/characters`),json(`/api/novels/${enc(state.novel)}/character-changes`)]);state.characters=data.characters||[];$('characterGrid').innerHTML=state.characters.length?state.characters.map((character,index)=>{const profile=character.personality_profile||{},fingerprint=[profile.desire&&`欲望：${profile.desire}`,profile.flaw&&`缺点：${profile.flaw}`,profile.contradiction&&`矛盾：${profile.contradiction}`].filter(Boolean).join(' · ');return`<article class="character" data-index="${index}"><span>${escapeHtml(character.ability_level||'普通人')}</span><h3>${escapeHtml(character.name)}</h3><p>${escapeHtml(character.personality||fingerprint||character.background||'尚未补充人物设定')}</p>${fingerprint&&character.personality?`<small>${escapeHtml(fingerprint)}</small>`:''}<small>${escapeHtml(character.current_status||'存活')}</small></article>`}).join(''):'<p class="hint">还没有人物。手动创建，或保存包含人物的章节后自动识别。</p>';$('characterChanges').innerHTML=(reviews.items||[]).map(item=>`<div class="chapter-row"><div><b>第${item.chapter}章 · ${escapeHtml(item.name)} · ${escapeHtml(item.field||'未结构化变化')}</b><small>${escapeHtml(item.change||item.new_value)}｜证据：${escapeHtml(item.evidence||'无')}</small></div><span><button class="secondary change-reject" data-id="${item.id}">拒绝</button> <button class="primary change-accept" data-id="${item.id}">接受</button></span></div>`).join('')||'<p class="hint">没有待确认的人物变化。</p>';document.querySelectorAll('.character').forEach(card=>card.onclick=()=>editCharacter(Number(card.dataset.index)));document.querySelectorAll('.change-accept,.change-reject').forEach(button=>button.onclick=async()=>{try{await post(`/api/novels/${enc(state.novel)}/character-changes/${button.dataset.id}/decide`,{accept:button.classList.contains('change-accept')});toast('人物变化已处理');await loadCharacters()}catch(error){toast(error.message,true)}})}
async function loadRelationshipGraph(){const data=await json(`/api/novels/${enc(state.novel)}/entities`),relations=(data.entities?.relationships||[]).slice(-30),panel=$('panel-characters');let box=$('relationshipGraph');if(!box){box=document.createElement('div');box.id='relationshipGraph';panel.append(box)}const names=[...new Set(relations.flatMap(item=>[item.from,item.to]))],width=760,height=360,cx=width/2,cy=height/2,radius=Math.min(width,height)*.36,positions=Object.fromEntries(names.map((name,index)=>[name,{x:cx+Math.cos(index/names.length*Math.PI*2)*radius,y:cy+Math.sin(index/names.length*Math.PI*2)*radius}]));box.innerHTML=`<h3>人物关系图</h3>${names.length?`<svg viewBox="0 0 ${width} ${height}" class="relation-svg">${relations.map(item=>{const a=positions[item.from],b=positions[item.to];return a&&b?`<g><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-5}">${escapeHtml(item.type||'关系')}</text></g>`:''}).join('')}${names.map(name=>{const p=positions[name];return`<g class="relation-node"><circle cx="${p.x}" cy="${p.y}" r="28"/><text x="${p.x}" y="${p.y+4}">${escapeHtml(name)}</text></g>`}).join('')}</svg>`:'<p class="hint">保存包含人物互动的章节后会形成关系图。</p>'}`}
