function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function ensureUtilityDialog(id,title){let dialog=$(id);if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id=id;dialog.innerHTML=`<form method="dialog" class="dialog-card"><button class="dialog-x" value="cancel">×</button><h2>${escapeHtml(title)}</h2><div class="utility-dialog-body"></div></form>`;document.body.append(dialog);return dialog}
function initAdvancedTools(){if(!state.novel)return;const stats=document.querySelector('.topbar .stats');if(stats&&!$('globalSearchBtn')){const button=document.createElement('button');button.id='globalSearchBtn';button.className='secondary';button.textContent='全书搜索';stats.prepend(button);button.onclick=runGlobalSearch}const storyActions=document.querySelector('#panel-story .page-head>div:last-child');if(storyActions&&!$('planningVersionsBtn')){const button=document.createElement('button');button.id='planningVersionsBtn';button.className='secondary';button.textContent='规划版本';storyActions.prepend(button);button.onclick=openPlanningVersions}const chapterActions=document.querySelector('#panel-chapters .page-head>div:last-child');if(chapterActions&&!$('reviewChapterBtn')){const button=document.createElement('button');button.id='reviewChapterBtn';button.className='secondary';button.textContent='审稿当前章节';chapterActions.prepend(button);button.onclick=reviewCurrentChapter}const characterPanel=$('panel-characters');if(characterPanel&&!$('characterArcs')){const title=document.createElement('h3');title.textContent='人物弧轨迹';const box=document.createElement('div');box.id='characterArcs';box.className='arc-grid';characterPanel.append(title,box);loadCharacterArcs().catch(console.warn)}observePlanningDrag();startHardwareMonitor();startEtaMonitor()}
async function runGlobalSearch(){const query=prompt('搜索正文、人物、设定、时间线和规划：','');if(!query)return;try{const [exact,semantic]=await Promise.all([json(`/api/novels/${enc(state.novel)}/search?q=${encodeURIComponent(query)}`),json(`/api/novels/${enc(state.novel)}/semantic-search?q=${encodeURIComponent(query)}`).catch(()=>({results:[]}))]),dialog=ensureUtilityDialog('searchDialog','全书混合搜索'),semanticHtml=(semantic.results||[]).map(item=>`<div class="search-result"><b>语义命中 · 第${item.chapter}章 · ${Math.round((item.score||0)*100)}%</b><small>${escapeHtml(item.reason||'')}</small><p>${escapeHtml(item.snippet)}</p></div>`).join(''),exactHtml=(exact.results||[]).map(item=>`<div class="search-result"><b>精确命中 · ${escapeHtml(item.file)}</b><p>${escapeHtml(item.snippet)}</p></div>`).join('');dialog.querySelector('.utility-dialog-body').innerHTML=semanticHtml+exactHtml||'<p class="hint">没有找到匹配内容。</p>';dialog.showModal()}catch(error){toast(error.message,true)}}
async function openPlanningVersions(){try{const data=await json(`/api/novels/${enc(state.novel)}/planning-versions`),dialog=ensureUtilityDialog('planningVersionsDialog','规划与人物版本');dialog.querySelector('.utility-dialog-body').innerHTML=`<textarea id="planningVersionDiff" rows="12" readonly placeholder="选择查看差异"></textarea>${(data.versions||[]).map(item=>`<div class="chapter-row"><div><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.created_at)}</small></div><span><button type="button" class="secondary planning-diff" data-id="${item.id}">差异</button> <button type="button" class="primary planning-restore" data-id="${item.id}">恢复</button></span></div>`).join('')||'<p class="hint">保存设定后会自动建立版本。</p>'}`;dialog.querySelectorAll('.planning-diff').forEach(button=>button.onclick=async()=>{$('planningVersionDiff').value=(await json(`/api/novels/${enc(state.novel)}/planning-versions/${button.dataset.id}/diff`)).diff});dialog.querySelectorAll('.planning-restore').forEach(button=>button.onclick=async()=>{if(!confirm('恢复会覆盖当前设定、人物和规划，当前状态会先自动备份。继续？'))return;await json(`/api/novels/${enc(state.novel)}/planning-versions/${button.dataset.id}/restore`,{method:'POST'});dialog.close();await loadBible();await loadCharacters();toast('规划版本已恢复')});dialog.showModal()}catch(error){toast(error.message,true)}}
async function reviewCurrentChapter(){const chapter=state.editing||state.chapter;if(!chapter)return toast('还没有可审查的章节',true);try{setBusy($('reviewChapterBtn'),true,'审稿中…');runtimeLog(`正在审查第${chapter}章，仅定位问题段落`);const data=await json(`/api/novels/${enc(state.novel)}/chapters/${chapter}/review`,{method:'POST'}),report=data.report||{},dialog=ensureUtilityDialog('chapterReviewDialog',`第${chapter}章审稿报告`);dialog.querySelector('.utility-dialog-body').innerHTML=`<div class="review-score"><b>${report.score??'--'}</b><span>${escapeHtml(report.summary||'')}</span></div>${(report.issues||[]).map(item=>`<article class="review-issue"><strong>${escapeHtml(item.type||'问题')}</strong><blockquote>${escapeHtml(item.quote||'')}</blockquote><p>${escapeHtml(item.reason||'')}</p><textarea rows="5">${escapeHtml(item.replacement||'')}</textarea></article>`).join('')||'<p class="hint">没有发现需要局部返修的明确问题。</p>'}`;dialog.showModal()}catch(error){toast(error.message,true)}finally{setBusy($('reviewChapterBtn'),false,'审稿当前章节')}}
async function loadCharacterArcs(){if(!$('characterArcs'))return;const data=await json(`/api/novels/${enc(state.novel)}/character-arcs`);$('characterArcs').innerHTML=(data.arcs||[]).map(arc=>`<article><h4>${escapeHtml(arc.name)} <small>${escapeHtml(arc.status)}</small></h4><div>${(arc.points||[]).map(point=>`<span><b>第${point.chapter}章 · ${escapeHtml(point.type)}</b>${escapeHtml(point.value)}</span>`).join('')||'<em>尚无变化记录</em>'}</div></article>`).join('')}
function observePlanningDrag(){const observer=new MutationObserver(()=>{const box=$('planningCards');if(!box)return;box.querySelectorAll('.planning-card').forEach((card,index)=>{card.draggable=true;card.dataset.index=index;card.ondragstart=event=>event.dataTransfer.setData('text/plain',card.dataset.index);card.ondragover=event=>event.preventDefault();card.ondrop=event=>{event.preventDefault();const from=Number(event.dataTransfer.getData('text/plain')),to=Number(card.dataset.index);if(from===to)return;try{const volumes=JSON.parse($('storyVolumes').value||'[]'),moved=volumes.splice(from,1)[0];volumes.splice(to,0,moved);let cursor=1;for(const volume of volumes){const length=Math.max(1,Number(volume.end_chapter||cursor)-Number(volume.start_chapter||cursor)+1);volume.start_chapter=cursor;volume.end_chapter=cursor+length-1;cursor=volume.end_chapter+1}volumes[volumes.length-1].end_chapter=Number($('storyTargetChapters').value)||volumes[volumes.length-1].end_chapter;$('storyVolumes').value=JSON.stringify(volumes,null,2);renderPlanningCards(volumes);toast('规划顺序已调整，保存设定后生效')}catch(error){toast('规划 JSON 无法调整：'+error.message,true)}}})});const panel=$('panel-story');if(panel)observer.observe(panel,{childList:true,subtree:true})}
function startHardwareMonitor(){setInterval(async()=>{if(!$('settingsDialog')?.open||!$('performanceBox'))return;try{const data=await json('/api/model/hardware-stats'),stats=data.stats||{};let line=$('hardwareLive');if(!line){line=document.createElement('p');line.id='hardwareLive';line.className='hardware-live';$('performanceBox').prepend(line)}line.textContent=`GPU ${stats.utilization??'--'}% · 专用显存 ${Math.round(stats.dedicated_mb||0)}MB · 温度/功耗 ${stats.temperature??'驱动未开放'}`}catch{}},3000)}
function startEtaMonitor(){let timer,start,base;document.querySelectorAll('#generateBtn,#continueBtn').forEach(button=>button.addEventListener('click',()=>{start=Date.now();base=editor.value.replace(/\s/g,'').length;clearInterval(timer);timer=setInterval(()=>{if(!state.generating){clearInterval(timer);return}const made=Math.max(0,editor.value.replace(/\s/g,'').length-base),elapsed=(Date.now()-start)/1000,target=Number($('targetWords').value),rate=made/Math.max(1,elapsed),remaining=rate?Math.max(0,(target-made)/rate):0;$('generationStatus').textContent=`正在生成 · ${rate.toFixed(1)}字/秒 · 预计剩余 ${Math.ceil(remaining)}秒`},3000)}))}
