function initAssetsPanel(){if(!state.novel||$('panel-assets'))return;const tab=document.createElement('button');tab.dataset.tab='assets';tab.textContent='创作资产';$('tabs').append(tab);const panel=document.createElement('section');panel.className='panel';panel.id='panel-assets';panel.innerHTML='<div class="page-head"><div><h2>创作资产</h2><p>统一管理场景、地点、势力、物品、名词和剧情试验分支。</p></div><button class="secondary" id="refreshAssets">刷新</button></div><div id="assetWorkspace"></div>';$('panel-timeline').after(panel);tab.onclick=async()=>{await openTab('assets');await loadAssets()};$('refreshAssets').onclick=loadAssets;initChapterAssetTools();initVoiceProfileTool()}
const assetLabels={scenes:['场景板','场景名称'],locations:['地点管理','地点名称'],factions:['势力管理','势力名称'],items:['物品管理','物品名称'],glossary:['名词词典','标准名词'],sandboxes:['剧情沙盒','分支名称'],subplots:['支线生命周期','支线名称'],secrets:['人物秘密','秘密名称'],calendar:['世界日历','日期或事件'],routes:['旅行路线','路线名称'],resources:['资源账本','资源名称'],conditions:['伤势与状态','状态名称'],dependencies:['章节依赖','依赖名称'],questions:['悬念管理','核心问题'],inspirations:['灵感收集箱','灵感标题'],research:['研究资料库','资料标题'],inventory:['章节库存','章节与状态'],workflows:['生成模板','模板名称'],publications:['发布记录','平台与批次'],visual_prompts:['视觉素材提示','封面或人物名称']};
async function loadAssets(){const data=await json(`/api/novels/${enc(state.novel)}/assets`),assets=data.assets||{};$('assetWorkspace').innerHTML=Object.entries(assetLabels).map(([kind,label])=>`<section class="asset-section"><header><div><h3>${label[0]}</h3><small>${(assets[kind]||[]).length}项</small></div><button class="primary asset-add" data-kind="${kind}">＋ 新增</button></header><div class="asset-grid">${(assets[kind]||[]).map(item=>`<article><h4>${escapeHtml(item.name||item.term||'未命名')}</h4><p>${escapeHtml(item.description||item.goal||item.definition||item.content||'')}</p><small>${escapeHtml(item.chapter?'第'+item.chapter+'章':'')}</small><button class="text-btn asset-edit" data-kind="${kind}" data-id="${item.id}">编辑</button><button class="text-btn asset-delete" data-kind="${kind}" data-id="${item.id}">删除</button></article>`).join('')||'<p class="hint">暂无内容</p>'}</div></section>`).join('');document.querySelectorAll('.asset-add').forEach(button=>button.onclick=()=>editAsset(button.dataset.kind));document.querySelectorAll('.asset-edit').forEach(button=>button.onclick=()=>editAsset(button.dataset.kind,(assets[button.dataset.kind]||[]).find(item=>item.id===button.dataset.id)));document.querySelectorAll('.asset-delete').forEach(button=>button.onclick=async()=>{if(!confirm('确定删除这项创作资产？'))return;await json(`/api/novels/${enc(state.novel)}/assets/${button.dataset.kind}/${button.dataset.id}`,{method:'DELETE'});await loadAssets()})}
async function editAsset(kind,item={}){const labels=assetLabels[kind],name=prompt(labels[1],item.name||item.term||'');if(!name)return;const description=prompt(kind==='glossary'?'定义、标准写法与禁用写法':kind==='scenes'?'章节、人物、地点、目标、阻力、转折和结果':kind==='sandboxes'?'从哪个节点分支、假设选择和预期影响':'说明、状态、关系或限制',item.description||item.definition||item.content||'');if(description===null)return;const payload={...item,name,description};if(kind==='glossary'){payload.term=name;payload.definition=description}if(kind==='sandboxes')payload.content=description;await json(`/api/novels/${enc(state.novel)}/assets/${kind}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadAssets();toast('创作资产已保存')}
function initChapterAssetTools(){const actions=document.querySelector('#panel-chapters .page-head>div:last-child');if(!actions||$('splitChapterBtn'))return;const split=document.createElement('button');split.id='splitChapterBtn';split.className='secondary';split.textContent='拆分最新章';const merge=document.createElement('button');merge.id='mergeChapterBtn';merge.className='secondary';merge.textContent='合并最后两章';actions.prepend(split,merge);split.onclick=async()=>{const chapter=state.chapter;if(!chapter)return;const content=(await json(`/api/novels/${enc(state.novel)}/chapters/${chapter}`)).content||'',position=Number(prompt(`输入拆分字符位置（100—${Math.max(100,content.length-100)}）`,Math.floor(content.length/2)));if(!position)return;await json(`/api/novels/${enc(state.novel)}/chapters/${chapter}/split`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({position})});state.chapter++;await loadChapters();toast('最新章节已拆分')};merge.onclick=async()=>{if(state.chapter<2||!confirm('合并最后两章？原章节会保留历史版本。'))return;await json(`/api/novels/${enc(state.novel)}/chapters/${state.chapter-1}/merge-next`,{method:'POST'});state.chapter--;await loadChapters();toast('最后两章已合并')}}
function initVoiceProfileTool(){const actions=$('characterDialog')?.querySelector('.dialog-actions');if(!actions||$('saveVoiceProfile'))return;const button=document.createElement('button');button.type='button';button.id='saveVoiceProfile';button.className='secondary';button.textContent='设置人物语气';actions.prepend(button);button.onclick=async()=>{const name=$('charName').value.trim();if(!name)return toast('请先选择人物',true);const sentence_style=prompt('常用句式、语速和停顿方式','');if(sentence_style===null)return;const vocabulary=prompt('常用词汇、口头禅和语言层次',''),addressing=prompt('对不同人物的称呼规则',''),emotion=prompt('不同情绪下的表达方式',''),forbidden=prompt('该人物绝不会使用的表达','');await json(`/api/novels/${enc(state.novel)}/characters/${enc(name)}/voice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sentence_style,vocabulary,addressing,emotion,forbidden})});toast('人物语气模板已保存')}}
