async function loadForeshadowWorkbench(){if(!$('assetWorkspace'))return;const data=await json(`/api/novels/${enc(state.novel)}/foreshadowing`);let section=$('foreshadowWorkbench');if(!section){section=document.createElement('section');section.id='foreshadowWorkbench';section.className='asset-section';$('assetWorkspace').append(section)}section.innerHTML=`<header><div><h3>伏笔操作台</h3><small>延后、提前、取消或删除</small></div></header><div class="asset-grid">${(data.items||[]).map(item=>`<article><h4>${item.status==='open'?'○':item.status==='resolved'?'✓':'×'} ${escapeHtml(item.text)}</h4><p>第${item.introduced_chapter}章建立 · 目标第${item.target_chapter}章</p><button class="text-btn foreshadow-reschedule" data-id="${item.id}" data-target="${item.target_chapter}">调整章节</button><button class="text-btn foreshadow-cancel" data-id="${item.id}">${item.status==='cancelled'?'重新开放':'取消'}</button><button class="text-btn foreshadow-delete" data-id="${item.id}">删除</button></article>`).join('')||'<p class="hint">还没有伏笔记录。</p>'}</div>`;section.querySelectorAll('.foreshadow-reschedule').forEach(button=>button.onclick=async()=>{const target=Number(prompt('新的目标回收章节',button.dataset.target));if(!target)return;await json(`/api/novels/${enc(state.novel)}/foreshadowing/${button.dataset.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_chapter:target})});await loadForeshadowWorkbench()});section.querySelectorAll('.foreshadow-cancel').forEach(button=>button.onclick=async()=>{await json(`/api/novels/${enc(state.novel)}/foreshadowing/${button.dataset.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:button.textContent==='取消'?'cancelled':'open'})});await loadForeshadowWorkbench()});section.querySelectorAll('.foreshadow-delete').forEach(button=>button.onclick=async()=>{if(!confirm('永久删除这条伏笔记录？'))return;await json(`/api/novels/${enc(state.novel)}/foreshadowing/${button.dataset.id}`,{method:'DELETE'});await loadForeshadowWorkbench()})}
document.querySelector('[data-tab="assets"]')?.addEventListener('click',()=>setTimeout(()=>loadForeshadowWorkbench().catch(console.warn),0));
function initNovelToolbox(){const panel=$('panel-assets');if(!panel||$('novelToolbox'))return;const box=document.createElement('section');box.id='novelToolbox';box.className='asset-section';box.innerHTML='<header><div><h3>小说工具箱</h3><small>回合、健康、候选、规则、批改与发布</small></div></header><div class="tool-grid"><button class="primary" id="chapterTurnsTool">章节回合</button><button class="secondary" id="projectHealthTool">工程健康</button><button class="secondary ai-novel-tool" data-tool="candidates">多候选生成</button><button class="secondary ai-novel-tool" data-tool="reverse-ending">结局反推</button><button class="secondary ai-novel-tool" data-tool="rule-check">规则推演</button><button class="secondary ai-novel-tool" data-tool="titles">批量章节标题</button><button class="secondary ai-novel-tool" data-tool="promotion">简介与宣传文案</button><button class="secondary" id="dialogueTool">对白提取</button><button class="secondary" id="batchReplaceTool">批量局部修改</button><button class="secondary" id="castStatsTool">群像与冲突曲线</button></div><div id="toolResult" class="tool-result"></div>';panel.insertBefore(box,$('assetWorkspace'));box.querySelectorAll('.ai-novel-tool').forEach(button=>button.onclick=()=>runNovelAiTool(button.dataset.tool));$('chapterTurnsTool').onclick=showChapterTurns;$('projectHealthTool').onclick=showProjectHealth;$('dialogueTool').onclick=extractDialogueTool;$('batchReplaceTool').onclick=batchReplaceTool;$('castStatsTool').onclick=loadCastStats}
async function showChapterTurns(){
 try{
  const data=await json(`/api/novels/${enc(state.novel)}/turns?limit=50`),turns=data.turns||[],dialog=ensureUtilityDialog('chapterTurnsDialog','章节回合与草稿正史');
  dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">AI 生成先进入草稿回合，只有提交后才会改变人物、事实、伏笔和时间线；superseded 表示已被更新正文取代。</p>${turns.map(item=>`<div class="chapter-row"><div><b>第${item.chapter}章 · ${escapeHtml(item.status)}</b><small>${item.words||0}字 · ${escapeHtml(item.source||'')} · ${escapeHtml(item.quality?.status||'')}</small></div><span>${!['committed','discarded','superseded'].includes(item.status)?`<button class="secondary turn-open" data-id="${item.id}">载入</button> <button class="secondary turn-preview" data-id="${item.id}">变化预览</button> <button class="primary turn-commit" data-id="${item.id}">提交正史</button> <button class="secondary turn-discard" data-id="${item.id}">废弃</button>`:''}</span></div>`).join('')||'<p class="hint">还没有章节回合。</p>'}`;
  dialog.showModal();
  dialog.querySelectorAll('.turn-open').forEach(button=>button.onclick=async()=>{const detail=await json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}`);editor.value=detail.content||'';state.editing=detail.inspection.turn.chapter;editor.dispatchEvent(new Event('input'));updateChapterLabel();dialog.close();await openTab('write');toast('草稿已载入，尚未提交正史')});
  dialog.querySelectorAll('.turn-preview').forEach(button=>button.onclick=async()=>{setBusy(button,true,'分析中…');try{const detail=await json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}/preview`,{method:'POST'}),preview=detail.preview||{},previewDialog=ensureUtilityDialog('turnPreviewDialog',`第${preview.chapter}章提交前变化`);previewDialog.querySelector('.utility-dialog-body').innerHTML=renderTurnChangePreview(preview);previewDialog.showModal()}catch(error){toast(error.message,true)}finally{setBusy(button,false,'变化预览')}});
  dialog.querySelectorAll('.turn-commit').forEach(button=>button.onclick=async()=>{let allowFacts=false,allowStale=false,allowLocks=false,allowClock=false,allowDecisions=false,allowSummary=false;try{const [previewResult,turnDetail]=await Promise.all([json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}/preview`,{method:'POST'}),json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}`)]),preview=previewResult.preview||{},factConflicts=preview.fact_conflicts||[],stateConflicts=preview.state_change_conflicts||[],conflicts=[...factConflicts,...stateConflicts],locks=preview.canonical_lock_conflicts||[],clock=preview.story_clock_issues||[],decisions=preview.character_decision_issues||[];if(turnDetail.inspection?.requires_plan_confirmation){allowStale=confirm('该草稿生成后上游规划已经变化。\n建议取消并重新生成；确定仍沿用旧草稿提交吗？');if(!allowStale)return}if(preview.analysis_degraded){allowSummary=confirm(`结构化摘要生成失败，人物、事实和时空检查不完整。\n${preview.analysis_error||''}\n\n建议取消并重新预览；仍要接受降级摘要吗？`);if(!allowSummary)return}if(conflicts.length){allowFacts=confirm(`检测到 ${factConflicts.length} 项硬事实变化、${stateConflicts.length} 项高风险状态变化：\n${conflicts.map(item=>item.message).join('\n')}\n\n确认这是有意改写并继续提交吗？`);if(!allowFacts)return}if(locks.length){allowLocks=confirm(`检测到权威设定锁冲突：\n${locks.map(item=>item.message).join('\n')}\n\n只有确实要修改锁定设定时才应继续。`);if(!allowLocks)return}if(clock.some(item=>item.blocking)){allowClock=confirm(`检测到故事时间或行程冲突：\n${clock.map(item=>item.message).join('\n')}\n\n确认仍要作为例外提交吗？`);if(!allowClock)return}if(decisions.some(item=>item.blocking)){allowDecisions=confirm(`检测到人物决定缺乏证据或转变诱因：\n${decisions.map(item=>item.message).join('\n')}\n\n确认仍要作为例外提交吗？`);if(!allowDecisions)return}const approvals={allow_fact_conflicts:allowFacts,allow_stale_planning:allowStale,allow_locked_changes:allowLocks,allow_story_clock_conflicts:allowClock,allow_character_decision_conflicts:allowDecisions,allow_degraded_summary:allowSummary};await json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}/commit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(approvals)});toast('回合已提交正史');dialog.close();await loadChapters()}catch(error){if(!confirm(`${error.message}\n仍要明确允许质量失败并提交吗？`))return;await json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}/commit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({allow_quality_failure:true,allow_fact_conflicts:allowFacts,allow_stale_planning:allowStale,allow_locked_changes:allowLocks,allow_story_clock_conflicts:allowClock,allow_character_decision_conflicts:allowDecisions,allow_degraded_summary:allowSummary})});toast('回合已强制提交正史');dialog.close();await loadChapters()}});
  dialog.querySelectorAll('.turn-discard').forEach(button=>button.onclick=async()=>{if(!confirm('废弃这个草稿回合？正史不会改变。'))return;await json(`/api/novels/${enc(state.novel)}/turns/${button.dataset.id}/discard`,{method:'POST'});dialog.close();await showChapterTurns()});
 }catch(error){toast(error.message,true)}
}
async function showProjectHealth(){try{const data=await json(`/api/novels/${enc(state.novel)}/health`),report=data.report||{},dialog=ensureUtilityDialog('projectHealthDialog','小说工程健康检查');dialog.querySelector('.utility-dialog-body').innerHTML=`<h3>${report.status==='healthy'?'✓ 工程健康':report.status==='unhealthy'?'⚠ 发现严重问题':'△ 建议检查'} · ${report.issue_count||0}项</h3><p class="hint">${report.chapters||0}章 · ${report.total_words||0}字 · 可自动修复${report.repairable_count||0}项</p>${(report.issues||[]).map(item=>`<div class="chapter-row"><b>${escapeHtml(item.severity)} · ${escapeHtml(item.kind)}</b><small>${escapeHtml(item.message)}${item.repairable?' · 可确定性修复':' · 需人工处理'}</small></div>`).join('')||'<p class="hint">摘要、提交标记、状态、回合与章节编号均正常。</p>'}${report.repairable_count?'<button type="button" class="primary" id="repairProjectHealth">修复可确定问题</button>':''}`;dialog.showModal();if($('repairProjectHealth'))$('repairProjectHealth').onclick=async()=>{if(!confirm('修复摘要、提交标记、派生账本和状态偏差？不会编造缺失章节。'))return;setBusy($('repairProjectHealth'),true,'修复中…');try{const fixed=await json(`/api/novels/${enc(state.novel)}/health/repair`,{method:'POST'});toast(`修复完成，剩余 ${fixed.after.issue_count} 项`);dialog.close();await showProjectHealth()}catch(error){toast(error.message,true)}}}catch(error){toast(error.message,true)}}
async function runNovelAiTool(tool){const instruction=prompt({candidates:'需要生成什么候选？例如：本章三个不同开头','reverse-ending':'描述目标结局状态','rule-check':'输入需要验证的能力用法或行动','titles':'输入标题风格要求','promotion':'输入目标平台和宣传侧重'}[tool],'');if(instruction===null)return;try{runtimeLog(`正在运行工具：${tool}`);const data=await json(`/api/novels/${enc(state.novel)}/ai-tool/${tool}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({instruction})});$('toolResult').innerHTML=`<h4>生成结果</h4><textarea rows="18">${escapeHtml(JSON.stringify(data.result,null,2))}</textarea>`;toast('AI工具已完成')}catch(error){toast(error.message,true)}}
async function extractDialogueTool(){const chapter=Number(prompt('提取第几章对白？',state.editing||state.chapter));if(!chapter)return;const data=await json(`/api/novels/${enc(state.novel)}/chapters/${chapter}/dialogue`);$('toolResult').innerHTML=`<h4>第${chapter}章对白 · ${data.count}段</h4><textarea rows="18">${escapeHtml((data.dialogue||[]).join('\n\n'))}</textarea>`}
async function batchReplaceTool(){const old=prompt('查找内容（会扫描全部章节）','');if(!old)return;const replacement=prompt('替换为','');if(replacement===null)return;if(!confirm(`确定在全部章节中将“${old}”替换为“${replacement}”？每章都会先保存历史版本。`))return;const data=await json(`/api/novels/${enc(state.novel)}/chapters/batch-replace`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({old,new:replacement})});toast(`已修改${data.changed_chapters}章，共替换${data.replacements}处`)}
async function loadCastStats(){const data=await json(`/api/novels/${enc(state.novel)}/cast-stats`);$('toolResult').innerHTML=`<h4>群像统计</h4><div class="asset-grid">${(data.characters||[]).map(item=>`<article><b>${escapeHtml(item.name)}</b><p>出场${item.chapters}章 · 提及${item.mentions}次 · 最后第${item.last_seen}章</p></article>`).join('')}</div><h4>冲突与对白曲线</h4><div class="curve-bars">${(data.conflict_curve||[]).map(item=>`<span style="--pressure:${Math.min(100,item.pressure*8)}%" title="第${item.chapter}章 压力${item.pressure} 对白${Math.round(item.dialogue_ratio*100)}%"><i></i><small>${item.chapter}</small></span>`).join('')}</div>`}
function renderTurnChangePreview(preview){
 const diff=preview.state_diff||{},totals=diff.totals||{},groups=[['状态变化',diff.state_changes||[]],['伏笔动作',diff.foreshadow_changes||[]],['人物认知',diff.knowledge_changes||[]]],riskLabel={high:'高风险',medium:'需留意',low:'低风险'};
 const cards=groups.map(([title,items])=>items.length?`<section class="asset-section"><header><div><h3>${title}</h3><small>${items.length}项</small></div></header>${items.map(item=>`<div class="chapter-row"><div><b>${escapeHtml(item.kind_label||'变化')} · ${escapeHtml(item.name||'')}</b><small>${escapeHtml(item.field||'')}：${escapeHtml(item.before||'未记录')} → ${escapeHtml(item.after||'')} ${item.target_chapter?`· 目标第${item.target_chapter}章`:''}</small></div><span class="${item.risk==='high'?'danger-text':''}">${riskLabel[item.risk]||item.risk||''}</span></div>`).join('')}</section>`:'').join('');
 const conflicts=preview.fact_conflicts||[];
 return `<p class="hint">此分析不会修改正史；正式提交会复用本次摘要。</p><div class="tool-result"><b>共 ${totals.all||0} 项变化</b> · 新增 ${totals.new||0} · 修改 ${totals.changed||0} · 高风险 ${totals.high_risk||0} · 需留意 ${totals.medium_risk||0}</div>${conflicts.length?`<section class="asset-section"><header><div><h3>硬事实冲突</h3><small>${conflicts.length}项，提交前必须确认</small></div></header>${conflicts.map(item=>`<div class="chapter-row"><b>高风险</b><small>${escapeHtml(item.message||JSON.stringify(item))}</small></div>`).join('')}</section>`:''}${cards||'<p class="hint">没有检测到人物、实体、伏笔或认知状态变化。</p>'}<details><summary>查看摘要原始数据</summary><textarea rows="18" readonly>${escapeHtml(JSON.stringify(preview,null,2))}</textarea></details>`;
}
