function initResearchUpload(){const grid=$('novelToolbox')?.querySelector('.tool-grid');if(!grid||$('researchUploadBtn'))return;const button=document.createElement('button');button.id='researchUploadBtn';button.className='secondary';button.textContent='导入研究资料';const input=document.createElement('input');input.id='researchUploadInput';input.type='file';input.accept='.txt,.md';input.hidden=true;grid.append(button,input);button.onclick=()=>input.click();input.onchange=async()=>{if(!input.files[0])return;const body=new FormData();body.append('file',input.files[0]);const response=await fetch(`/api/novels/${enc(state.novel)}/assets/research/upload`,{method:'POST',body}),data=await response.json();if(!response.ok)throw new Error(data.error||'上传失败');toast('研究资料已导入，仅作为事实参考');await loadAssets()}}
