function initExtraAiTools(){const grid=$('novelToolbox')?.querySelector('.tool-grid');if(!grid||$('extraTool-action-director'))return;const tools={'action-director':'动作场面导演','chapter-mode':'章节模式转换','trim':'自动精简','suspense':'悬念密度检查','climax':'高潮检查','viewpoint':'角色视角改写','exit-impact':'死亡/退场影响','goal-conflicts':'人物目标冲突','reader-sim':'读者模拟器','recap':'前情提要','understanding':'理解测试','audiobook':'有声书脚本','comic':'漫画分镜','translate':'多语言翻译','visual':'封面/立绘提示','platform-format':'发布格式'};Object.entries(tools).forEach(([tool,label])=>{const button=document.createElement('button');button.id=`extraTool-${tool}`;button.className='secondary';button.textContent=label;button.onclick=()=>runExtraAiTool(tool,label);grid.append(button)})}
async function runExtraAiTool(tool,label){const instruction=prompt(`${label}：请输入章节、人物或具体要求`,'');if(instruction===null)return;try{runtimeLog(`正在运行${label}`);const data=await json(`/api/novels/${enc(state.novel)}/ai-tool/${tool}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({instruction})});$('toolResult').innerHTML=`<h4>${escapeHtml(label)}</h4><textarea rows="18">${escapeHtml(JSON.stringify(data.result,null,2))}</textarea>`}catch(error){toast(error.message,true)}}
initExtraAiTools();
function initBrowserWritingTools(){const head=document.querySelector('.editor-head>div:last-child');if(!head||$('readAloudBtn'))return;const focus=document.createElement('button'),speak=document.createElement('button'),dictate=document.createElement('button');focus.className=speak.className=dictate.className='secondary';focus.textContent='专注阅读';speak.textContent='朗读';dictate.textContent='语音输入';focus.onclick=()=>document.body.classList.toggle('focus-reading');speak.id='readAloudBtn';speak.onclick=()=>{speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(editor.value);utterance.lang='zh-CN';speechSynthesis.speak(utterance)};dictate.onclick=()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return toast('当前浏览器不支持语音识别',true);const recognition=new Recognition();recognition.lang='zh-CN';recognition.continuous=true;recognition.onresult=event=>{for(let index=event.resultIndex;index<event.results.length;index++)editor.value+=event.results[index][0].transcript;editor.dispatchEvent(new Event('input'))};recognition.start();toast('语音输入已开始，再次刷新页面可停止')};head.prepend(focus,speak,dictate);const grid=$('novelToolbox')?.querySelector('.tool-grid');if(!grid)return;[['clipboardTool','剪贴板归档',archiveClipboard],['snapshotTool','世界状态快照',showWorldSnapshot],['batchReviewTool','批量审稿',runBatchReview]].forEach(([id,label,handler])=>{const button=document.createElement('button');button.id=id;button.className='secondary';button.textContent=label;button.onclick=handler;grid.append(button)})}
async function archiveClipboard(){try{const text=await navigator.clipboard.readText();if(!text.trim())return toast('剪贴板没有文字',true);const name=prompt('归档标题','剪贴板灵感');if(!name)return;await json(`/api/novels/${enc(state.novel)}/assets/inspirations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,description:text})});toast('剪贴板内容已归档到灵感箱')}catch(error){toast('无法读取剪贴板：'+error.message,true)}}
async function showWorldSnapshot(){const chapter=Number(prompt('查看第几章结束时的世界状态',state.editing||state.chapter));if(!chapter)return;const data=await json(`/api/novels/${enc(state.novel)}/world-snapshot/${chapter}`);$('toolResult').innerHTML=`<h4>第${chapter}章世界快照</h4><textarea rows="20">${escapeHtml(JSON.stringify(data.snapshot,null,2))}</textarea>`}
async function runBatchReview(){const value=prompt('输入1至5个章节号，用逗号分隔',String(state.chapter));if(!value)return;const chapters=value.split(/[,，]/).map(Number).filter(Boolean).slice(0,5);runtimeLog(`正在串行审查 ${chapters.length} 章`);const data=await json(`/api/novels/${enc(state.novel)}/batch-review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chapters})});$('toolResult').innerHTML=`<h4>批量审稿汇总</h4><textarea rows="22">${escapeHtml(JSON.stringify(data.reports,null,2))}</textarea>`}
initBrowserWritingTools();
function organizeFeaturePanels(){const toolbox=$('novelToolbox');if(toolbox&&!toolbox.closest('details')){const details=document.createElement('details');details.className='feature-drawer';details.innerHTML='<summary>AI 专项工具与分析（按需展开）</summary>';toolbox.before(details);details.append(toolbox)}const workspace=$('assetWorkspace');if(workspace&&!$('assetFilters')){const filters=document.createElement('div');filters.id='assetFilters';filters.className='asset-filters';filters.innerHTML='<button class="primary" data-group="plot">剧情</button><button class="secondary" data-group="world">世界</button><button class="secondary" data-group="material">资料</button><button class="secondary" data-group="workflow">工作流</button><button class="secondary" data-group="all">全部</button>';workspace.before(filters);filters.querySelectorAll('button').forEach(button=>button.onclick=()=>{filters.querySelectorAll('button').forEach(item=>item.className=item===button?'primary':'secondary');filterAssetSections(button.dataset.group)});new MutationObserver(()=>filterAssetSections(filters.querySelector('.primary')?.dataset.group||'plot')).observe(workspace,{childList:true})}}
function filterAssetSections(group){const groups={plot:['场景板','剧情沙盒','支线生命周期','章节依赖','悬念管理','人物秘密'],world:['地点管理','势力管理','物品管理','世界日历','旅行路线','资源账本','伤势与状态'],material:['名词词典','灵感收集箱','研究资料库'],workflow:['章节库存','生成模板','发布记录','视觉素材提示']};document.querySelectorAll('#assetWorkspace>.asset-section').forEach(section=>{const title=section.querySelector('h3')?.textContent||'';section.hidden=group!=='all'&&!(groups[group]||[]).includes(title)})}
organizeFeaturePanels();
async function applySavedSettings(){try{const data=await json('/api/settings'),settings=data.settings;state.settings=settings;if($('targetWords'))$('targetWords').value=String(settings.default_target_words);if($('batchWords'))$('batchWords').value=settings.default_target_words;if($('batchCount'))$('batchCount').value=settings.default_batch_chapters;if($('batchStopWarning'))$('batchStopWarning').checked=settings.stop_batch_on_warning}catch(error){console.warn(error)}}
applySavedSettings();
if(state.novel)refreshWritingContext().catch(console.warn);
restoreTaskCenter().then(()=>{if(state.activeTask){lastTaskEvent=0;watchTask(state.activeTask)}});
function initProductionCenter(){if(!state.novel||$('productionCenter'))return;const host=$('panel-dashboard');if(!host)return;const section=document.createElement('section');section.id='productionCenter';section.className='production-center';section.innerHTML=`<div class="page-head"><div><h2>创作控制中心</h2><p>统一工作流、场景规划、状态记忆、题材策略与长篇质量。</p></div><button class="secondary" id="refreshProduction">刷新</button></div><div class="production-grid"><article class="control-card"><h3>可恢复工作流</h3><div id="workflowCards"></div></article><article class="control-card"><h3>题材方法包</h3><select id="genrePackSelect"></select><button class="primary" id="applyGenrePack">应用方法包</button><div id="genrePackInfo" class="hint"></div></article><article class="control-card"><h3>场景级细纲</h3><p id="sceneOutlineInfo" class="hint"></p><div class="control-actions"><button class="primary" id="generateSceneOutline">AI 生成下一章细纲</button><button class="secondary" id="editSceneOutline">查看/编辑 JSON</button></div></article><article class="control-card"><h3>Prompt 最终预览</h3><p class="hint">显示模型真正收到的系统提示词、上下文和 Token 来源。</p><button class="secondary" id="previewChapterPrompt">预览下一章提示词</button></article><article class="control-card"><h3>章节交接审核</h3><div id="memoryReviewCard" class="hint"></div></article><article class="control-card"><h3>动态状态卡</h3><div id="stateCardSummary" class="hint"></div></article><article class="control-card wide"><h3>剧情分支沙盒</h3><div class="control-actions"><button class="primary" id="generateSandbox">生成三个候选方向</button></div><div id="sandboxList"></div></article><article class="control-card"><h3>规划影响传播</h3><div id="planningImpactList" class="hint"></div></article><article class="control-card"><h3>长篇一致性基线</h3><div id="longEvalCard" class="hint"></div><button class="secondary" id="runQualityWorkflow">重新评测</button></article><article class="control-card wide"><details><summary>AI 动作注册表</summary><div id="aiActionRegistry"></div></details></article></div>`;host.append(section);$('refreshProduction').onclick=loadProductionCenter;$('applyGenrePack').onclick=applyGenrePack;$('generateSceneOutline').onclick=generateNextSceneOutline;$('editSceneOutline').onclick=editNextSceneOutline;$('previewChapterPrompt').onclick=previewChapterPrompt;$('generateSandbox').onclick=generateSandbox;$('runQualityWorkflow').onclick=()=>startWorkflow('quality_sweep');loadProductionCenter().catch(error=>toast(error.message,true))}
async function loadProductionCenter(){if(!state.novel||!$('productionCenter'))return;const [workflows,actions,packs,scenes,memory,cards,sandboxes,impacts,evaluation]=await Promise.all([json('/api/workflows'),json('/api/ai-actions'),json(`/api/novels/${enc(state.novel)}/genre-packs`),json(`/api/novels/${enc(state.novel)}/scene-outlines`),json(`/api/novels/${enc(state.novel)}/chapter-memory`),json(`/api/novels/${enc(state.novel)}/state-cards`),json(`/api/novels/${enc(state.novel)}/sandboxes`),json(`/api/novels/${enc(state.novel)}/planning-impacts`),json(`/api/novels/${enc(state.novel)}/long-form-evaluation`)]);$('workflowCards').innerHTML=workflows.workflows.map(item=>`<div class="mini-workflow"><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.description)} · ${escapeHtml(item.model_calls)}</small><button class="secondary workflow-start" data-key="${item.key}">运行</button></div>`).join('');document.querySelectorAll('.workflow-start').forEach(button=>button.onclick=()=>startWorkflow(button.dataset.key));$('genrePackSelect').innerHTML=packs.packs.map(item=>`<option value="${item.key}" ${item.active?'selected':''}>${escapeHtml(item.label)}</option>`).join('');const active=packs.packs.find(item=>item.active)||packs.packs[0];$('genrePackInfo').textContent=active?[...(active.rules||[]),...(active.avoid||[]).map(item=>`避免：${item}`)].join('；'):'未设置';const next=state.chapter+1,scene=(scenes.items||[]).find(item=>Number(item.chapter)===next);$('sceneOutlineInfo').textContent=scene?`第${next}章 · ${scene.scenes.length}个场景 · 目标${scene.total_target_words}字 · ${scene.status}`:`第${next}章尚无场景细纲`;renderMemoryReview(memory);const stateTypes=Object.entries(cards.cards||{});$('stateCardSummary').innerHTML=stateTypes.map(([kind,items])=>`${escapeHtml(kind)}：${Object.keys(items||{}).length}`).join('<br>')||'还没有动态状态卡';renderSandboxes(sandboxes.items||[]);renderPlanningImpacts(impacts.items||[]);renderLongEvaluation(evaluation.report||{});$('aiActionRegistry').innerHTML=(actions.actions||[]).map(item=>`<div class="registry-row"><b>${escapeHtml(item.category)} / ${escapeHtml(item.label)}</b><small>读：${escapeHtml(item.reads.join('、'))}<br>写：${escapeHtml(item.writes.join('、'))}<br>Prompt：${escapeHtml(item.prompt_key)} · ${escapeHtml(item.profile)}</small></div>`).join('')}
async function startWorkflow(key){try{const values={target_words:Number($('targetWords')?.value||5000),count:key==='serial_chapters'?Math.max(1,Math.min(10,Number(prompt('连续生成多少章？','3')||0))):1,stop_on_warning:true,scene_mode:Boolean($('sceneWritingMode')?.checked)};if(key==='serial_chapters'&&!values.count)return;const data=await json(`/api/novels/${enc(state.novel)}/workflows/${key}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});runtimeLog(`工作流 ${key} 已进入队列${values.scene_mode?' · 逐场景模式':''}`);watchTask(data.task_id)}catch(error){toast(error.message,true)}}
async function applyGenrePack(){try{const key=$('genrePackSelect').value;await json(`/api/novels/${enc(state.novel)}/genre-packs/${key}`,{method:'POST'});toast('题材方法包已应用，下一次生成生效');await loadProductionCenter()}catch(error){toast(error.message,true)}}
async function generateNextSceneOutline(){const chapter=state.chapter+1;try{setBusy($('generateSceneOutline'),true,'生成中…');runtimeLog(`正在生成第${chapter}章场景细纲`);const data=await json(`/api/novels/${enc(state.novel)}/scene-outlines/${chapter}/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target_words:Number($('targetWords')?.value||5000)})});runtimeLog(`场景细纲完成 · ${data.metrics?.tokens_per_second||0} token/s`,'token');await loadProductionCenter()}catch(error){toast(error.message,true)}finally{setBusy($('generateSceneOutline'),false,'AI 生成下一章细纲')}}
async function editNextSceneOutline(){const chapter=state.chapter+1;try{const data=await json(`/api/novels/${enc(state.novel)}/scene-outlines/${chapter}`),dialog=ensureUtilityDialog('sceneOutlineDialog',`第${chapter}章场景细纲`);dialog.querySelector('.utility-dialog-body').innerHTML=`<textarea id="sceneOutlineJson" rows="24">${escapeHtml(JSON.stringify(data.item||{chapter,opening_hook:'',ending_hook:'',scenes:[{title:'场景1',summary:'',characters:[],location:'',goal:'',obstacle:'',turn:'',outcome:'',emotion:'',target_words:800}]},null,2))}</textarea><button type="button" class="primary" id="saveSceneOutlineJson">保存并确认</button>`;dialog.showModal();$('saveSceneOutlineJson').onclick=async()=>{const payload=JSON.parse($('sceneOutlineJson').value);payload.status='confirmed';await json(`/api/novels/${enc(state.novel)}/scene-outlines/${chapter}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});dialog.close();toast('场景细纲已确认');await loadProductionCenter()}}catch(error){toast(error.message,true)}}
async function previewChapterPrompt(){try{setBusy($('previewChapterPrompt'),true,'装配中…');const data=await json(`/api/novels/${enc(state.novel)}/prompt-preview/chapter_write?chapter=${state.chapter+1}&target_words=${Number($('targetWords')?.value||5000)}`),dialog=ensureUtilityDialog('promptPreviewDialog','下一章最终 Prompt');dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">${data.context_stats.tokens} / ${data.context_stats.budget} tokens · ${(data.context_stats.segments||[]).slice(0,8).map(item=>`${escapeHtml(item.label)} ${item.tokens}t`).join(' · ')}</p><h3>System</h3><textarea rows="10" readonly>${escapeHtml(data.system)}</textarea><h3>User + Context</h3><textarea rows="24" readonly>${escapeHtml(data.user)}</textarea>`;dialog.showModal()}catch(error){toast(error.message,true)}finally{setBusy($('previewChapterPrompt'),false,'预览下一章提示词')}}
function renderMemoryReview(memory){const handoff=memory.handoff||{},reconciliation=memory.plan_reconciliation||{},rows=[...(handoff.open_loops||[]).map(item=>`未闭环：${item}`),...(reconciliation.new_constraints||[]).map(item=>`新增约束：${item}`),...(reconciliation.next_chapter_impacts||[]).map(item=>`下一章影响：${item}`)];$('memoryReviewCard').innerHTML=`<b>第${memory.chapter||0}章 · ${escapeHtml(reconciliation.review_status||'unavailable')}</b><br>${rows.map(escapeHtml).join('<br>')||'暂无待审核结构化约束'}${memory.chapter?`<div class="control-actions"><button class="secondary" id="editMemory">编辑交接</button>${reconciliation.review_status==='pending'?'<button class="primary" id="confirmMemory">确认约束</button><button class="secondary" id="dismissMemory">忽略对账</button>':''}</div>`:''}`;if($('editMemory'))$('editMemory').onclick=()=>editMemoryReview(memory);if($('confirmMemory'))$('confirmMemory').onclick=()=>reviewMemory(memory.chapter,'confirmed');if($('dismissMemory'))$('dismissMemory').onclick=()=>reviewMemory(memory.chapter,'dismissed')}
async function editMemoryReview(memory){const handoff=memory.handoff||{},reconciliation=memory.plan_reconciliation||{},dialog=ensureUtilityDialog('memoryEditDialog',`第${memory.chapter}章交接审核`),editable={state_changes:handoff.state_changes||[],knowledge_changes:handoff.knowledge_changes||[],commitments:handoff.commitments||[],open_loops:handoff.open_loops||[],immediate_next_intent:handoff.immediate_next_intent||'',completed_goals:reconciliation.completed_goals||[],unfinished_goals:reconciliation.unfinished_goals||[],deviations:reconciliation.deviations||[],new_constraints:reconciliation.new_constraints||[],next_chapter_impacts:reconciliation.next_chapter_impacts||[]};dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">只修改结构化交接，不会修改正文。确认后新增约束才会作为下一章硬约束。</p><textarea id="memoryEditJson" rows="24">${escapeHtml(JSON.stringify(editable,null,2))}</textarea><div class="dialog-actions"><button type="button" class="secondary" id="saveMemoryDraft">保存待确认</button><button type="button" class="primary" id="saveMemoryConfirmed">保存并确认</button></div>`;dialog.showModal();const save=async status=>{try{const edits=JSON.parse($('memoryEditJson').value);await json(`/api/novels/${enc(state.novel)}/chapter-memory/${memory.chapter}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,edits})});dialog.close();toast(status==='confirmed'?'交接修改已确认':'交接修改已保存');await loadProductionCenter()}catch(error){toast(error.message,true)}};$('saveMemoryDraft').onclick=()=>save('pending');$('saveMemoryConfirmed').onclick=()=>save('confirmed')}
async function reviewMemory(chapter,status){try{await json(`/api/novels/${enc(state.novel)}/chapter-memory/${chapter}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});toast(status==='confirmed'?'交接约束已确认':'本次计划对账已忽略');await loadProductionCenter()}catch(error){toast(error.message,true)}}
async function generateSandbox(){const question=prompt('想探索什么剧情问题？','下一章有哪些合理、意外但不破坏既定事实的推进方向？');if(!question)return;try{setBusy($('generateSandbox'),true,'推演中…');runtimeLog('正在单次调用模型生成三个隔离剧情方向');const data=await json(`/api/novels/${enc(state.novel)}/sandboxes/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question})});runtimeLog(`剧情沙盒完成 · ${data.metrics?.tokens_per_second||0} token/s`,'token');await loadProductionCenter()}catch(error){toast(error.message,true)}finally{setBusy($('generateSandbox'),false,'生成三个候选方向')}}
function renderSandboxes(items){const open=items.filter(item=>item.status==='open').slice(-3).reverse();$('sandboxList').innerHTML=open.map(box=>`<div class="sandbox-box"><b>${escapeHtml(box.question)}</b>${box.variants.map(item=>`<article><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.direction)}</p><small>收益：${escapeHtml((item.benefits||[]).join('；'))}<br>风险：${escapeHtml((item.risks||[]).join('；'))}</small><button class="secondary adopt-variant" data-box="${box.id}" data-variant="${item.id}">采纳此方向</button></article>`).join('')}</div>`).join('')||'<p class="hint">还没有开放的剧情沙盒。</p>';document.querySelectorAll('.adopt-variant').forEach(button=>button.onclick=async()=>{if(!confirm('采纳后会写入下一章目标，确定继续？'))return;await json(`/api/novels/${enc(state.novel)}/sandboxes/${button.dataset.box}/adopt/${button.dataset.variant}`,{method:'POST'});toast('候选方向已采纳');await loadProductionCenter()})}
function renderPlanningImpacts(items){const pending=items.filter(item=>item.status==='pending').slice(-8).reverse();$('planningImpactList').innerHTML=pending.map(item=>`<div class="impact-row"><b>影响第 ${item.chapters.join('、')} 章</b><small>${escapeHtml(item.message)}</small><button class="secondary resolve-impact" data-id="${item.id}">已复核</button></div>`).join('')||'没有待处理的规划传播影响';document.querySelectorAll('.resolve-impact').forEach(button=>button.onclick=async()=>{await json(`/api/novels/${enc(state.novel)}/planning-impacts/${button.dataset.id}/resolve`,{method:'POST'});await loadProductionCenter()})}
function renderLongEvaluation(report){$('longEvalCard').innerHTML=`<b class="eval-score">${report.score??0}</b> 分<br>交接覆盖 ${Math.round((report.memory_coverage||0)*100)}% · 规划贴合 ${Math.round((report.planning_alignment||0)*100)}% · 状态卡 ${report.state_cards||0}<br>${(report.issues||[]).map(escapeHtml).join('<br>')||'当前基线未发现明显缺口'}`}
async function reviewChapterWithApply(){const chapter=state.editing||state.chapter;if(!chapter)return toast('还没有可审查的章节',true);try{setBusy($('reviewChapterBtn'),true,'审稿中…');runtimeLog(`正在审查第${chapter}章，仅定位问题段落`);const data=await json(`/api/novels/${enc(state.novel)}/chapters/${chapter}/review`,{method:'POST'}),report=data.report||{},issues=report.issues||[],dialog=ensureUtilityDialog('chapterReviewDialog',`第${chapter}章审稿报告`);dialog.querySelector('.utility-dialog-body').innerHTML=`<div class="review-score"><b>${report.score??'--'}</b><span>${escapeHtml(report.summary||'')}</span></div>${issues.map((item,index)=>`<article class="review-issue"><strong>${escapeHtml(item.type||'问题')}</strong><blockquote>${escapeHtml(item.quote||'')}</blockquote><p>${escapeHtml(item.reason||'')}</p><textarea rows="5" data-review-replacement="${index}">${escapeHtml(item.replacement||'')}</textarea><button type="button" class="primary apply-review-fix" data-index="${index}">应用此处修订</button></article>`).join('')||'<p class="hint">没有发现需要局部返修的明确问题。</p>'}`;dialog.showModal();dialog.querySelectorAll('.apply-review-fix').forEach(button=>button.onclick=async()=>{const index=Number(button.dataset.index),issue=issues[index],replacement=dialog.querySelector(`[data-review-replacement="${index}"]`).value;if(!issue?.quote||!replacement)return toast('缺少可替换原文或修订稿',true);setBusy(button,true,'应用中…');try{const request=allow=>json(`/api/novels/${enc(state.novel)}/chapters/${chapter}/apply-review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quote:issue.quote,replacement,allow_fact_conflicts:allow})});let result;try{result=await request(false)}catch(error){if(!String(error.message).includes('硬事实')||!confirm(`${error.message}\n\n确认修订确实要改变该事实吗？`))throw error;result=await request(true)}if(state.editing===chapter||state.chapter===chapter){editor.value=result.content;editor.dispatchEvent(new Event('input'))}toast('局部修订已应用，章节记忆已重建');dialog.close()}catch(error){toast(error.message,true)}finally{setBusy(button,false,'应用此处修订')}})}catch(error){toast(error.message,true)}finally{setBusy($('reviewChapterBtn'),false,'审稿当前章节')}}
if($('reviewChapterBtn'))$('reviewChapterBtn').onclick=reviewChapterWithApply;
async function initGovernanceTools(){const grid=document.querySelector('#productionCenter .production-grid');if(!grid||$('stateProposalCard'))return;const stateCard=document.createElement('article');stateCard.className='control-card wide';stateCard.id='stateProposalCard';stateCard.innerHTML='<h3>权威状态裁决</h3><div id="stateProposalList" class="hint">加载中…</div>';const promptCard=document.createElement('article');promptCard.className='control-card wide';promptCard.id='promptRegressionCard';promptCard.innerHTML='<h3>Prompt 快照回归</h3><div id="promptSnapshotList" class="hint">加载中…</div>';grid.append(stateCard,promptCard);await Promise.all([loadStateProposals(),loadPromptSnapshots()])}
async function loadStateProposals(){const host=$('stateProposalList');if(!host)return;const data=await json(`/api/novels/${enc(state.novel)}/state-proposals?status=pending`);host.innerHTML=(data.items||[]).map(item=>`<div class="impact-row"><b>${escapeHtml(item.risk)} · ${escapeHtml(item.kind)}/${escapeHtml(item.name)} · ${escapeHtml(item.field)}</b><small>${escapeHtml(item.previous||'未记录')} → ${escapeHtml(item.value)}<br>证据：${escapeHtml(item.evidence||'无')}</small><button class="primary state-proposal" data-id="${item.id}" data-accept="1">确认</button><button class="secondary state-proposal" data-id="${item.id}" data-accept="">拒绝</button></div>`).join('')||'没有待裁决的高风险状态变化';host.querySelectorAll('.state-proposal').forEach(button=>button.onclick=async()=>{await json(`/api/novels/${enc(state.novel)}/state-proposals/${button.dataset.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accept:Boolean(button.dataset.accept)})});await Promise.all([loadStateProposals(),loadProductionCenter()])})}
async function loadPromptSnapshots(){const host=$('promptSnapshotList');if(!host)return;const data=await json('/api/prompt-snapshots');host.innerHTML=(data.items||[]).map(item=>`<div class="impact-row"><b>${escapeHtml(item.task_type)}</b><small>${escapeHtml(item.hash.slice(0,12))} · ${escapeHtml(item.created_at||'')} · ${item.has_baseline?'已有基线':'尚无基线'}</small><button class="secondary prompt-baseline" data-task="${escapeHtml(item.task_type)}">设为基线</button><button class="secondary prompt-compare" data-task="${escapeHtml(item.task_type)}">比较</button></div>`).join('')||'运行一次模型任务后，这里会出现最终 Prompt 快照';host.querySelectorAll('.prompt-baseline').forEach(button=>button.onclick=async()=>{await json(`/api/prompt-snapshots/${encodeURIComponent(button.dataset.task)}/baseline`,{method:'POST'});toast('Prompt 基线已保存');await loadPromptSnapshots()});host.querySelectorAll('.prompt-compare').forEach(button=>button.onclick=async()=>{const data=await json(`/api/prompt-snapshots/${encodeURIComponent(button.dataset.task)}/compare`),dialog=ensureUtilityDialog('promptDiffDialog',`${button.dataset.task} Prompt 差异`);dialog.querySelector('.utility-dialog-body').innerHTML=`<textarea rows="24" readonly>${escapeHtml((data.result.diff||[data.result.status]).join('\n'))}</textarea>`;dialog.showModal()})}
