async function initRagQualityTools(){const grid=document.querySelector('#productionCenter .production-grid');if(!grid||$('ragQualityCard'))return;const card=document.createElement('article');card.className='control-card wide';card.id='ragQualityCard';card.innerHTML='<h3>RAG 检索评测与作者偏好</h3><div id="authorPreferenceSummary" class="hint">加载中…</div><div class="control-actions"><button class="secondary" id="runRagEvaluation">运行检索黄金集评测</button></div>';grid.append(card);const preferences=await json(`/api/novels/${enc(state.novel)}/author-preferences`);const profile=preferences.profile||{};$('authorPreferenceSummary').textContent=profile.sample_count?`已从${profile.sample_count}次修改学习：段落约${profile.preferred_paragraph_length}字 · 句子约${profile.preferred_sentence_length}字 · 对白约${Math.round((profile.preferred_dialogue_ratio||0)*100)}%`:'尚未积累作者修改样本；手动修改并保存 AI 章节后会自动学习';$('runRagEvaluation').onclick=runRagEvaluation}
async function runRagEvaluation(){const raw=prompt('每行填写：检索问题|期望命中的章节号（多个用逗号）','关键钥匙由谁保管|1\n主角在哪里发现线索|2');if(!raw)return;const cases=raw.split(/\n/).map((line,index)=>{const [query,chapters='']=line.split('|');return{id:`case-${index+1}`,query:query?.trim(),expected_chapters:chapters.split(/[,，]/).map(Number).filter(Boolean)}}).filter(item=>item.query&&item.expected_chapters.length);if(!cases.length)return toast('没有有效评测项',true);runtimeLog(`正在评测 ${cases.length} 个 RAG 问题`);const data=await json(`/api/novels/${enc(state.novel)}/rag-evaluate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cases,top_k:5})}),report=data.report||{},dialog=ensureUtilityDialog('ragEvalDialog','RAG 检索评测');dialog.querySelector('.utility-dialog-body').innerHTML=`<h3>Hit@5 ${Math.round((report.hit_at_k||0)*100)}% · MRR ${(report.mrr||0).toFixed(3)}</h3><textarea rows="22" readonly>${escapeHtml(JSON.stringify(report.results,null,2))}</textarea>`;dialog.showModal()}
setTimeout(()=>initRagQualityTools().catch(console.warn),40);
async function initHistoryRevisionTools(){const grid=document.querySelector('#productionCenter .production-grid');if(!grid||$('historyRevisionCard'))return;const card=document.createElement('article');card.className='control-card wide';card.id='historyRevisionCard';card.innerHTML='<h3>历史剧情事务修改</h3><p class="hint">允许修改已经发生的事实；系统会扫描前置铺垫和后续结果，在隔离分支修补并通过后原子提交。</p><div class="control-actions"><button class="primary" id="createHistoryRevision">创建历史修改</button><button class="secondary" id="refreshHistoryRevisions">刷新</button></div><div id="historyRevisionList" class="hint"></div>';grid.append(card);$('createHistoryRevision').onclick=openHistoryRevisionDialog;$('refreshHistoryRevisions').onclick=loadHistoryRevisions;await loadHistoryRevisions()}
async function loadHistoryRevisions(){
 const host=$('historyRevisionList');if(!host)return;const data=await json(`/api/novels/${enc(state.novel)}/history-revisions`);
 host.innerHTML=(data.items||[]).slice(0,8).map(item=>`<div class="impact-row"><b>第${item.source_chapter}章 · ${escapeHtml(item.status||'')}</b><small>${escapeHtml(item.old_fact||'')} → ${escapeHtml(item.new_fact||'')}<br>${escapeHtml(item.mode||'')}</small><button class="secondary history-impact" data-id="${item.id}">影响</button>${['validated','needs_review'].includes(item.status)?`<button class="secondary history-candidates" data-id="${item.id}">候选差异</button>`:''}${item.status==='validated'?`<button class="primary history-commit" data-id="${item.id}">提交</button>`:''}${!['committed','aborted'].includes(item.status)?`<button class="secondary history-abort" data-id="${item.id}">废弃</button>`:''}</div>`).join('')||'尚无历史修改事务';
 host.querySelectorAll('.history-impact').forEach(button=>button.onclick=async()=>{try{const data=await json(`/api/novels/${enc(state.novel)}/history-revisions/${button.dataset.id}`),dialog=ensureUtilityDialog('historyImpactDialog','历史修改影响清单');dialog.querySelector('.utility-dialog-body').innerHTML=renderHistoryImpact(data.item.impact||{});dialog.showModal()}catch(error){toast(error.message,true)}});
 host.querySelectorAll('.history-candidates').forEach(button=>button.onclick=()=>showHistoryCandidates(button.dataset.id));
 host.querySelectorAll('.history-commit').forEach(button=>button.onclick=async()=>{const data=await json(`/api/novels/${enc(state.novel)}/history-revisions/${button.dataset.id}/commit`,{method:'POST'});watchTask(data.task_id)});
 host.querySelectorAll('.history-abort').forEach(button=>button.onclick=async()=>{await json(`/api/novels/${enc(state.novel)}/history-revisions/${button.dataset.id}/abort`,{method:'POST'});await loadHistoryRevisions()})
}
async function showHistoryCandidates(revisionId){try{const data=await json(`/api/novels/${enc(state.novel)}/history-revisions/${revisionId}/preview`),preview=data.preview||{},items=preview.items||[],dialog=ensureUtilityDialog('historyCandidatesDialog','历史修改候选正文');dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">提交前逐章检查差异，可直接修改候选正文并重新验证。</p><label>影响章节<select id="historyCandidateChapter">${items.map((item,index)=>`<option value="${index}">第${item.chapter}章 · ${escapeHtml(item.direction||'')} · ${item.changed?'已修改':'未变化'}</option>`).join('')}</select></label><label>候选正文<textarea id="historyCandidateContent" rows="20"></textarea></label><label>与原文差异<textarea id="historyCandidateDiff" rows="14" readonly></textarea></label><div id="historyCandidateValidation" class="hint"></div><button type="button" class="primary" id="saveHistoryCandidate" ${['committed','aborted','committing'].includes(preview.status)?'disabled':''}>保存候选并重新验证</button>`;const render=()=>{const item=items[Number($('historyCandidateChapter').value)||0];$('historyCandidateContent').value=item?.candidate||'';$('historyCandidateDiff').value=item?.diff||'候选正文与原文相同';const issues=preview.validation?.issues||[];$('historyCandidateValidation').textContent=`状态：${preview.status||''} · 验证问题 ${issues.length} 项${issues.length?' · '+issues.map(value=>value.message).join('；'):''}`};$('historyCandidateChapter').onchange=render;render();$('saveHistoryCandidate').onclick=async()=>{const item=items[Number($('historyCandidateChapter').value)||0];if(!item)return;setBusy($('saveHistoryCandidate'),true,'保存验证中…');try{await json(`/api/novels/${enc(state.novel)}/history-revisions/${revisionId}/candidates/${item.chapter}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:$('historyCandidateContent').value})});dialog.close();toast('候选正文已保存并重新验证');await loadHistoryRevisions();await showHistoryCandidates(revisionId)}catch(error){toast(error.message,true)}finally{setBusy($('saveHistoryCandidate'),false,'保存候选并重新验证')}};dialog.showModal()}catch(error){toast(error.message,true)}}
function renderHistoryImpact(impact){const ledger=impact.ledger_impacts||{},categories=ledger.categories||{},chapters=impact.chapters||[];return`<div class="dashboard-grid"><article class="dashboard-stat"><small>正文影响章</small><b>${chapters.length}</b></article><article class="dashboard-stat"><small>前置铺垫</small><b>${impact.backward_count||0}</b></article><article class="dashboard-stat"><small>后续结果</small><b>${impact.forward_count||0}</b></article><article class="dashboard-stat ${ledger.risk_level==='高'?'warn':''}"><small>跨账本风险</small><b>${escapeHtml(ledger.risk_level||'低')}</b></article></div><h3>正文修改范围</h3><div class="list-card">${chapters.map(item=>`<div class="chapter-row"><b>第${item.chapter}章 · ${escapeHtml(item.direction)}</b><small>${escapeHtml(item.reason||'')}<br>${escapeHtml((item.dependency_types||[]).join('、'))}</small></div>`).join('')||'<p class="hint">未发现正文依赖</p>'}</div><h3>结构化账本影响</h3><div class="list-card">${Object.entries(categories).map(([,item])=>`<div class="chapter-row"><b>${escapeHtml(item.label)} · ${item.count}项</b><small>${escapeHtml(item.items.map(row=>`${row.chapters.length?'第'+row.chapters.join('、')+'章 · ':''}${row.action}`).join('；'))}</small></div>`).join('')||'<p class="hint">未发现额外结构化依赖</p>'}</div>${(ledger.warnings||[]).map(item=>`<p class="hint">${escapeHtml(item)}</p>`).join('')}`}
function openHistoryRevisionDialog(){
 const dialog=ensureUtilityDialog('historyRevisionDialog','创建历史剧情修改');dialog.querySelector('.utility-dialog-body').innerHTML=`<label>事实发生章<input id="historySourceChapter" type="number" min="1" value="${Math.max(1,state.chapter)}"></label><label>原历史事实<textarea id="historyOldFact" rows="4" placeholder="例如：第20章顾临川在爆炸中死亡"></textarea></label><label>修改后的事实<textarea id="historyNewFact" rows="4" placeholder="例如：顾临川重伤失踪，其他人物误以为他死亡"></textarea></label><label>附加要求<textarea id="historyInstruction" rows="3" placeholder="可留空"></textarea></label><label>修订方式<select id="historyMode"><option value="minimal_patch">最小修补</option><option value="range_rewrite">影响区间重写</option><option value="replan_forward">修改并重规划后续</option></select></label><label class="inline-check"><input id="historyAutoCommit" type="checkbox"> 验证通过后自动原子提交（高风险，不推荐）</label><div class="control-actions"><button class="secondary" id="analyzeHistoryRevision">仅分析影响</button><button class="primary" id="startHistoryRevision" disabled>确认影响并开始</button></div><div id="historyImpactPreview" class="tool-result"><p class="hint">先分析影响，不会调用模型或修改任何文件。</p></div>`;
 const payload=()=>({source_chapter:Number($('historySourceChapter').value),old_fact:$('historyOldFact').value.trim(),new_fact:$('historyNewFact').value.trim(),instruction:$('historyInstruction').value.trim(),mode:$('historyMode').value,auto_commit:$('historyAutoCommit').checked});
 const invalidate=()=>{$('startHistoryRevision').disabled=true;$('historyImpactPreview').innerHTML='<p class="hint">输入已变化，请重新分析影响。</p>'};
 ['historySourceChapter','historyOldFact','historyNewFact'].forEach(id=>$(id).addEventListener('input',invalidate));dialog.showModal();
 $('analyzeHistoryRevision').onclick=async()=>{const dataToSend=payload();if(!dataToSend.source_chapter||!dataToSend.old_fact||!dataToSend.new_fact)return toast('发生章、原事实和新事实不能为空',true);setBusy($('analyzeHistoryRevision'),true,'分析中…');try{const data=await json(`/api/novels/${enc(state.novel)}/history-revisions/analyze`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(dataToSend)});$('historyImpactPreview').innerHTML=renderHistoryImpact(data.impact);$('startHistoryRevision').disabled=false}catch(error){toast(error.message,true)}finally{setBusy($('analyzeHistoryRevision'),false,'仅分析影响')}};
 $('startHistoryRevision').onclick=async()=>{const dataToSend=payload();setBusy($('startHistoryRevision'),true,'建立分支…');try{const data=await json(`/api/novels/${enc(state.novel)}/history-revisions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(dataToSend)});dialog.close();runtimeLog(`历史修改影响：前置${data.item.impact.backward_count}章 · 后续${data.item.impact.forward_count}章`);watchTask(data.task_id);await loadHistoryRevisions()}catch(error){toast(error.message,true)}finally{setBusy($('startHistoryRevision'),false,'确认影响并开始')}}
}
setTimeout(()=>initHistoryRevisionTools().catch(console.warn),60);

