async function loadProductionControlHub(){
 if(!state.novel||!$('productionCenter'))return;const data=await json(`/api/novels/${enc(state.novel)}/production-control`),grid=$('productionCenter').querySelector('.production-grid');let card=$('productionControlHub');if(!card){card=document.createElement('article');card.id='productionControlHub';card.className='control-card wide';grid.prepend(card)}const p=data.policy||{},r=data.rhythm||{},b=data.budget||{},m=data.manuscript||{},issues=data.issues||{};
 card.innerHTML=`<h3>自动连载生产总控</h3><p class="hint">单模型串行 · 当前${p.enabled?'运行中':'已停止'} · 节奏建议：${escapeHtml(r.recommended||'')}（${escapeHtml(r.reason||'')}）</p><div class="form-grid"><label>目标写到第几章<input id="serialTarget" type="number" min="1" max="1000" value="${p.target_chapter||100}"></label><label>每轮章节数<input id="serialBatch" type="number" min="1" max="10" value="${p.batch_size||1}"></label><label>每章目标字数<input id="serialWords" type="number" min="500" max="20000" value="${p.target_words||5000}"></label><label>章节间冷却秒数<input id="serialCooldown" type="number" min="0" max="3600" value="${p.cooldown_seconds||0}"></label><label>失败重试次数<input id="serialRetries" type="number" min="0" max="5" value="${p.max_retries||0}"></label><label>提交策略<select id="serialCommit"><option value="review">每章确认</option><option value="balanced">质量异常确认</option><option value="automatic">自动提交非失败章</option></select></label><label class="check-row"><input id="serialStopWarning" type="checkbox" ${p.stop_on_warning?'checked':''}><span>严重警告时停止</span></label><label class="check-row"><input id="serialSceneMode" type="checkbox" ${p.scene_mode?'checked':''}><span>逐场景长章模式</span></label></div><div class="control-actions"><button class="secondary" id="saveSerialPolicy">保存策略</button><button class="${p.enabled?'secondary':'primary'}" id="toggleSerial">${p.enabled?'停止自动连载':'启动自动连载'}</button><button class="secondary" id="openPlanningTree">规划树工作台</button><button class="secondary" id="openIssueCenter">逻辑问题中心 (${issues.total||0})</button><button class="secondary" id="openCandidateCenter">章节候选稿</button><button class="secondary" id="openBudgetReport">预算与成稿编排</button></div><div class="dashboard-grid"><article class="dashboard-stat"><small>预计10章调用</small><b>${b.estimated_calls||0}</b></article><article class="dashboard-stat"><small>预计耗时</small><b>${b.estimated_hours||0}h</b></article><article class="dashboard-stat"><small>已编排章节</small><b>${m.chapter_count||0}</b></article><article class="dashboard-stat"><small>成稿总字数</small><b>${m.total_words||0}</b></article></div>`;
 card.querySelector('.form-grid').insertAdjacentHTML('beforeend',`<label>允许开始小时<input id="serialStartHour" type="number" min="0" max="23" value="${p.allowed_start_hour??0}"></label><label>允许结束小时<input id="serialEndHour" type="number" min="1" max="24" value="${p.allowed_end_hour??24}"></label><label>连续失败熔断<input id="serialFailureLimit" type="number" min="1" max="10" value="${p.breaker_failure_limit||3}"></label><label>连续短章熔断<input id="serialShortLimit" type="number" min="1" max="10" value="${p.breaker_short_chapter_limit||2}"></label><label>最低速度 token/s<input id="serialMinSpeed" type="number" min="0" max="500" step="0.1" value="${p.minimum_tokens_per_second??15}"></label><label class="check-row"><input id="serialNotifications" type="checkbox" ${p.notification_enabled?'checked':''}><span>桌面通知</span></label>`);const stats=data.statistics||{},runtime=data.runtime||{};card.querySelector('.dashboard-grid').insertAdjacentHTML('beforeend',`<article class="dashboard-stat"><small>平均速度</small><b>${stats.average_tokens_per_second||0} t/s</b></article><article class="dashboard-stat"><small>平均耗时</small><b>${stats.average_elapsed_seconds||0}s</b></article><article class="dashboard-stat"><small>人工干预率</small><b>${stats.manual_intervention_rate||0}%</b></article><article class="dashboard-stat ${runtime.state==='tripped'?'warn':''}"><small>熔断状态</small><b>${escapeHtml(runtime.state||'idle')}</b></article>`);if(runtime.last_stop_reason)card.insertAdjacentHTML('beforeend',`<p class="hint danger-text">最近停止原因：${escapeHtml(runtime.last_stop_reason)}</p>`);$('serialCommit').value=p.commit_mode||'balanced';$('saveSerialPolicy').onclick=saveSerialPolicy;$('toggleSerial').onclick=()=>toggleSerialControl(Boolean(p.enabled));$('openPlanningTree').onclick=openPlanningTreeWorkbench;$('openIssueCenter').onclick=()=>openActionableProductionIssues(issues);$('openCandidateCenter').onclick=openChapterCandidateCenter;$('openBudgetReport').onclick=()=>openBudgetAndManuscript(b,m);$('serialNotifications').onchange=()=>{if($('serialNotifications').checked)requestDesktopNotifications()};
}
function serialPolicyPayload(){const notification_enabled=$('serialNotifications').checked;localStorage.setItem('novel-desktop-notifications',notification_enabled?'1':'0');return{target_chapter:Number($('serialTarget').value),batch_size:Number($('serialBatch').value),target_words:Number($('serialWords').value),cooldown_seconds:Number($('serialCooldown').value),max_retries:Number($('serialRetries').value),commit_mode:$('serialCommit').value,stop_on_warning:$('serialStopWarning').checked,scene_mode:$('serialSceneMode').checked,allowed_start_hour:Number($('serialStartHour').value),allowed_end_hour:Number($('serialEndHour').value),breaker_failure_limit:Number($('serialFailureLimit').value),breaker_short_chapter_limit:Number($('serialShortLimit').value),minimum_tokens_per_second:Number($('serialMinSpeed').value),notification_enabled}}
async function saveSerialPolicy(){try{await json(`/api/novels/${enc(state.novel)}/production-control/policy`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(serialPolicyPayload())});toast('自动连载策略已保存');await loadProductionControlHub()}catch(error){toast(error.message,true)}}
async function toggleSerialControl(enabled){try{if(!enabled)await saveSerialPolicy();const data=await json(`/api/novels/${enc(state.novel)}/production-control/${enabled?'stop':'start'}`,{method:'POST'});toast(enabled?`自动连载已停止，取消${data.cancelled_queued||0}个排队回合`:'自动连载已启动');if(data.task_id)watchTask(data.task_id);await loadProductionControlHub()}catch(error){toast(error.message,true)}}
async function openPlanningTreeWorkbench(){try{const data=await json(`/api/novels/${enc(state.novel)}/planning-tree`),tree=data.tree||{},dialog=ensureUtilityDialog('planningTreeDialog','规划树工作台'),nodes=[...(tree.sources||[]),{id:'volumes',label:'全部分卷',content:tree.volumes?.map(item=>item.data)||[]} ,...(tree.chapters||[]).map(item=>({id:item.id,label:`第${item.chapter}章提要${item.locked?' · 场景已锁定':''}`,content:item.brief||{chapter:item.chapter}}))];dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">人工保存后会自动标记受影响章节、失效旧规划并保护已提交正史。</p><label>规划节点<select id="planningTreeNode">${nodes.map((item,index)=>`<option value="${index}">${escapeHtml(item.label||item.id)}</option>`).join('')}</select></label><textarea id="planningTreeContent" rows="24"></textarea><button class="primary" id="savePlanningTreeNode">保存节点并传播影响</button>`;const render=()=>{const item=nodes[Number($('planningTreeNode').value)||0];$('planningTreeContent').value=typeof item.content==='string'?item.content:JSON.stringify(item.content,null,2)};$('planningTreeNode').onchange=render;render();$('savePlanningTreeNode').onclick=async()=>{const item=nodes[Number($('planningTreeNode').value)||0];let value=$('planningTreeContent').value;if(item.id==='volumes'||item.id.startsWith('chapter:'))value=JSON.parse(value);await json(`/api/novels/${enc(state.novel)}/planning-tree/${encodeURIComponent(item.id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:value})});dialog.close();toast('规划节点已保存，影响已传播');await loadProductionControlHub()};dialog.showModal()}catch(error){toast(error.message,true)}}
function openProductionIssues(issues){const dialog=ensureUtilityDialog('productionIssuesDialog','逻辑问题处理中心'),labels={consistency:'一致性',quality_debts:'质量债务',fact_conflicts:'事实冲突',overdue_foreshadowing:'逾期伏笔',open_promises:'开放承诺',planning_impacts:'规划影响'};dialog.querySelector('.utility-dialog-body').innerHTML=Object.entries(issues.groups||{}).map(([key,items])=>`<h3>${labels[key]||key} · ${(items||[]).length}</h3><div class="list-card">${(items||[]).map(item=>`<div class="chapter-row"><small>${escapeHtml(item.message||item.description||item.text||JSON.stringify(item))}</small></div>`).join('')||'<p class="hint">没有问题</p>'}</div>`).join('');dialog.showModal()}
function openActionableProductionIssues(issues){const dialog=ensureUtilityDialog('productionIssuesDialog','逻辑问题处理中心'),labels={consistency:'一致性',quality_debts:'质量债务',fact_conflicts:'事实冲突',overdue_foreshadowing:'逾期伏笔',open_promises:'开放承诺',planning_impacts:'规划影响'},groups=issues.groups||{};dialog.querySelector('.utility-dialog-body').innerHTML=Object.entries(groups).map(([key,items])=>`<h3>${labels[key]||key} · ${(items||[]).length}</h3><div class="list-card">${(items||[]).map((item,index)=>`<div class="chapter-row"><small>${escapeHtml(item.message||item.description||item.text||JSON.stringify(item))}</small><span>${key==='consistency'?`<button class="secondary issue-jump" data-group="${key}" data-index="${index}">跳转章节</button>`:`<button class="primary issue-resolve" data-group="${key}" data-index="${index}">处理</button>`}</span></div>`).join('')||'<p class="hint">没有问题</p>'}</div>`).join('');dialog.querySelectorAll('.issue-jump').forEach(button=>button.onclick=async()=>{const item=groups[button.dataset.group][Number(button.dataset.index)],chapter=Number(item.chapter||item.new?.chapter||0);dialog.close();if(chapter){await loadChapter(chapter);await openTab('write')}else toast('该问题没有明确章节，请在规划树中处理',true)});dialog.querySelectorAll('.issue-resolve').forEach(button=>button.onclick=async()=>{const item=groups[button.dataset.group][Number(button.dataset.index)],group=button.dataset.group;let action='resolve',extra={};if(group==='overdue_foreshadowing'){const choice=prompt('输入 resolve 回收、cancel 取消，或新的目标章节','resolve');if(!choice)return;if(/^\d+$/.test(choice)){action='reschedule';extra.target_chapter=Number(choice)}else action=choice}else if(group==='open_promises'){action=confirm('确定标记该叙事承诺已兑现？取消将把它标记为取消。')?'resolve':'cancel'}else if(group==='fact_conflicts'||group==='quality_debts'){extra.resolution=prompt('填写处理说明','已人工确认并处理')||'已人工处理'}await json(`/api/novels/${enc(state.novel)}/production-issues/${encodeURIComponent(item.issue_id)}/action`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})});toast('问题已处理');dialog.close();await loadProductionControlHub()});dialog.showModal()}
async function requestDesktopNotifications(){if(!('Notification'in window))return toast('当前浏览器不支持桌面通知',true);if(Notification.permission==='default')await Notification.requestPermission();toast(Notification.permission==='granted'?'桌面通知已启用':'桌面通知未获授权',Notification.permission!=='granted')}
const runtimeLogWithoutDesktopNotification=runtimeLog;runtimeLog=function(message,type){runtimeLogWithoutDesktopNotification(message,type);if(localStorage.getItem('novel-desktop-notifications')==='0'||!('Notification'in window)||Notification.permission!=='granted')return;const text=String(message||'');if(/完成|失败|等待确认|暂停|熔断/.test(text)){const key=`${type||''}:${text}`;if(window.__lastNovelNotification!==key){window.__lastNovelNotification=key;new Notification('小说生产任务',{body:text.slice(0,240)})}}};
async function openChapterCandidateCenter(){try{const chapter=state.editing||state.chapter||1,data=await json(`/api/novels/${enc(state.novel)}/chapter-candidates/${chapter}`),items=data.items||[],dialog=ensureUtilityDialog('candidateCenterDialog',`第${chapter}章候选稿`);dialog.querySelector('.utility-dialog-body').innerHTML=`<p class="hint">当前编辑器正文可保存为独立候选，不会改变正史；勾选两稿可比较差异，最终在“章节回合”中提交。</p><label>候选名称<input id="candidateLabel" value="候选稿 ${(items.length||0)+1}"></label><div class="control-actions"><button class="primary" id="saveCurrentCandidate">把当前编辑器保存为候选</button><button class="secondary" id="compareCandidates">比较勾选的两稿</button></div><div class="list-card">${items.map(item=>`<label class="chapter-row"><input type="checkbox" class="candidate-select" value="${item.id}"><span><b>${escapeHtml(item.metadata?.label||'候选稿')}</b><small>${item.words||0}字 · ${escapeHtml(item.status||'')}</small></span></label>`).join('')||'<p class="hint">还没有候选稿</p>'}</div>`;$('saveCurrentCandidate').onclick=async()=>{if(!editor.value.trim())return toast('编辑器没有正文',true);await json(`/api/novels/${enc(state.novel)}/chapter-candidates`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chapter,content:editor.value,label:$('candidateLabel').value,target_words:Number($('targetWords')?.value||5000)})});dialog.close();toast('候选稿已隔离保存')};$('compareCandidates').onclick=async()=>{const selected=[...dialog.querySelectorAll('.candidate-select:checked')].map(input=>input.value);if(selected.length!==2)return toast('请正好勾选两个候选稿',true);const result=await json(`/api/novels/${enc(state.novel)}/chapter-candidate-comparisons/${selected[0]}/${selected[1]}`),diffDialog=ensureUtilityDialog('candidateDiffDialog',`第${chapter}章候选差异`);diffDialog.querySelector('.utility-dialog-body').innerHTML=`<textarea rows="28" readonly>${escapeHtml(result.diff||'内容相同')}</textarea>`;diffDialog.showModal()};dialog.showModal()}catch(error){toast(error.message,true)}}
function openBudgetAndManuscript(budget,manuscript){const dialog=ensureUtilityDialog('budgetManuscriptDialog','模型任务预算与成稿编排');dialog.querySelector('.utility-dialog-body').innerHTML=`<div class="dashboard-grid"><article class="dashboard-stat"><small>预计调用</small><b>${budget.estimated_calls||0}</b></article><article class="dashboard-stat"><small>预计输出Token</small><b>${budget.estimated_output_tokens||0}</b></article><article class="dashboard-stat"><small>预计时间</small><b>${budget.estimated_hours||0}h</b></article></div>${(manuscript.volumes||[]).map(volume=>`<h3>${escapeHtml(volume.title)} · ${volume.words||0}字</h3><div class="list-card">${(volume.chapters||[]).map(item=>`<div class="chapter-row"><b>第${item.chapter}章 ${escapeHtml(item.title||'')}</b><small>${item.words||0}字</small></div>`).join('')||'<p class="hint">本卷尚无正文</p>'}</div>`).join('')}<div class="control-actions"><button class="secondary manuscript-export" data-format="txt">导出TXT</button><button class="secondary manuscript-export" data-format="docx">导出DOCX</button><button class="secondary manuscript-export" data-format="epub">导出EPUB</button></div>`;dialog.querySelectorAll('.manuscript-export').forEach(button=>button.onclick=()=>window.location.href=`/api/novels/${enc(state.novel)}/export/${button.dataset.format}`);dialog.showModal()}
async function loadProductionStatisticsCard(){if(!state.novel||!$('productionCenter'))return;const data=await json(`/api/novels/${enc(state.novel)}/production-statistics`),stats=data.statistics||{},grid=$('productionCenter').querySelector('.production-grid');let card=$('productionStatisticsCard');if(!card){card=document.createElement('article');card.id='productionStatisticsCard';card.className='control-card wide';grid.append(card)}card.innerHTML=`<h3>生产统计趋势</h3><div class="dashboard-grid"><article class="dashboard-stat"><small>平均速度</small><b>${stats.average_tokens_per_second||0} t/s</b></article><article class="dashboard-stat"><small>任务失败率</small><b>${stats.task_failure_rate||0}%</b></article><article class="dashboard-stat"><small>任务暂停率</small><b>${stats.task_pause_rate||0}%</b></article><article class="dashboard-stat"><small>人工干预率</small><b>${stats.manual_intervention_rate||0}%</b></article><article class="dashboard-stat"><small>模型调用</small><b>${stats.model_calls||0}</b></article></div><div class="list-card">${(stats.trend||[]).slice().reverse().map(item=>`<div class="chapter-row"><b>第${item.chapter}章 · ${escapeHtml(item.quality||'未记录质量')}</b><small>${item.tokens_per_second||0} token/s · ${item.elapsed_seconds||0}秒 · ${item.calls||0}次调用${item.revised?' · 已修订':''}</small></div>`).join('')||'<p class="hint">生成并提交章节后显示趋势。</p>'}</div>`}
setTimeout(()=>{loadReleaseReadiness().catch(console.warn);loadProductionControlHub().catch(console.warn);loadProductionStatisticsCard().catch(console.warn);if($('refreshProduction'))$('refreshProduction').onclick=async()=>{try{await loadProductionCenter();await loadReleaseReadiness();await loadProductionControlHub();await loadProductionStatisticsCard()}catch(error){toast(error.message,true)}}},120);

async function syncSidebarModelStatus(){
 try{
  const status=await json('/api/model/status'),model=(status.loaded_models||[])[0]||{};
  const context=Number(model.contextLength||model.context_length||0);
  if($('sidebarModelName')&&(model.displayName||model.identifier))$('sidebarModelName').textContent=model.displayName||model.identifier;
  if($('sidebarModelContext'))$('sidebarModelContext').textContent=context?`${Math.round(context/1024)}K`:'未加载';
  $('sidebarModelDot')?.classList.toggle('online',Boolean(status.loaded));
 }catch(error){console.warn('模型状态同步失败',error)}
}
setTimeout(syncSidebarModelStatus,40);
